/**
 * Shared OIDC helpers for Space Fractions (space-fractions.md lines 10-14,
 * 37-44).
 *
 * Responsibilities:
 *   - Validate a Bearer OIDC access token's issuer and audience against the
 *     configured OIDC_ISSUER and expected audience.
 *   - Validate the token signature against JWKS fetched from OIDC_JWKS_URI.
 *   - Extract the verified `sub` and realm/access roles for authorization.
 *
 * Environment contract (space-fractions.md line 40):
 *   - OIDC_ISSUER       public issuer origin (e.g. http://localhost:8080/realms/space-fractions)
 *   - OIDC_JWKS_URI     internal-certificate endpoint, defaults to
 *                       http://keycloak:8080/realms/space-fractions/protocol/openid-connect/certs
 *   - OIDC_AUDIENCE     expected token audience (default "account")
 *
 * The JWT signature and claims are verified with the `jose` package (RFC 7519 /
 * RFC 7515 / RFC 7517). A short in-memory JWKS cache avoids refetching keys per
 * request; keys are refetched when an unknown `kid` is encountered.
 */

const { createRemoteJWKSet, jwtVerify } = require('jose');

/** Error thrown when a token/credential is missing or invalid (=> HTTP 401). */
class AuthError extends Error {
  constructor(message) {
    super(message);
    this.name = 'AuthError';
  }
}

/** Error thrown when a verified principal is not authorized (=> HTTP 403). */
class ForbiddenError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ForbiddenError';
  }
}

const DEFAULT_JWKS_URI =
  'http://keycloak:8080/realms/space-fractions/protocol/openid-connect/certs';

/**
 * Normalize an issuer string by stripping a single trailing slash so the
 * `iss` claim (which Keycloak emits without a trailing slash) compares equal to
 * a configured OIDC_ISSUER that users enter with one.
 *
 * @param {string} issuer
 * @returns {string}
 */
function normalizeIssuer(issuer) {
  if (typeof issuer !== 'string') return '';
  return issuer.replace(/\/+$/, '');
}

/**
 * Build an OIDC token verifier bound to configured issuer/audience/JWKS.
 *
 * @param {object} [options]
 * @param {string} [options.issuer]    expected issuer (default process.env.OIDC_ISSUER)
 * @param {string} [options.audience]  expected audience (default OIDC_AUDIENCE || 'account')
 * @param {string} [options.jwksUri]   JWKS endpoint (default OIDC_JWKS_URI)
 * @returns {{ verify(token: string): Promise<object> }}
 */
function createTokenVerifier(options = {}) {
  const issuer = options.issuer ?? process.env.OIDC_ISSUER ?? '';
  const audience = options.audience ?? (process.env.OIDC_AUDIENCE || 'account');
  const jwksUri = options.jwksUri ?? process.env.OIDC_JWKS_URI ?? DEFAULT_JWKS_URI;

  let jwks = null;
  let cachedIssuer = null;
  let cachedAudience = null;

  /**
   * Verify a raw JWT string. Resolves to the decoded payload when the token is
   * structurally, cryptographically and claim-valid; otherwise rejects with an
   * AuthError.
   *
   * @param {string} token
   * @returns {Promise<object>} JWT payload (contains sub, realm_access, etc.)
   */
  async function verify(token) {
    if (!issuer) {
      throw new AuthError('OIDC issuer not configured');
    }
    if (typeof token !== 'string' || token.length === 0) {
      throw new AuthError('missing bearer token');
    }

    // (Re)build the remote JWKS when issuer/audience change between calls.
    if (!jwks || cachedIssuer !== issuer || cachedAudience !== audience) {
      jwks = createRemoteJWKSet(new URL(jwksUri));
      cachedIssuer = issuer;
      cachedAudience = audience;
    }

    try {
      const { payload } = await jwtVerify(token, jwks, {
        issuer: normalizeIssuer(issuer),
        audience: audience,
        algorithms: ['RS256'],
      });
      if (!payload.sub || typeof payload.sub !== 'string') {
        throw new AuthError('token missing subject claim');
      }
      return payload;
    } catch (err) {
      if (err instanceof AuthError) throw err;
      // jose throws on signature/expiry/issuer/audience mismatch.
      throw new AuthError(`token verification failed: ${err.code || err.message}`);
    }
  }

  return { verify };
}

