 * Extract the list of role strings from a JWT payload. Handles both Keycloak's
 * realm_access.roles and resource_access.<client>.roles forms, returning a
 * unified flat array.
 *
 * @param {object} payload JWT payload
 * @returns {string[]}
 */
function extractRoles(payload) {
  const roles = new Set();
  if (payload && payload.realm_access && Array.isArray(payload.realm_access.roles)) {
    for (const r of payload.realm_access.roles) roles.add(r);
  }
  if (payload && payload.resource_access && typeof payload.resource_access === 'object') {
    for (const clientKey of Object.keys(payload.resource_access)) {
      const clientRoles = payload.resource_access[clientKey];
      if (clientRoles && Array.isArray(clientRoles.roles)) {
        for (const r of clientRoles.roles) roles.add(r);
      }
    }
  }
  return Array.from(roles);
}

/**
 * Determine whether a JWT payload carries the administrator role.
 *
 * @param {object} payload JWT payload
 * @returns {boolean}
 */
function isAdmin(payload) {
  return extractRoles(payload).includes('admin');
}

/**
 * Parse an HTTP Authorization header and return the Bearer token, or throw an
 * AuthError when the header is missing/malformed.
 *
 * @param {string|undefined} header
 * @returns {string}
 */
function bearerToken(header) {
  if (typeof header !== 'string' || !header.startsWith('Bearer ')) {
    throw new AuthError('missing bearer token');
  }
  const token = header.slice('Bearer '.length).trim();
  if (token === '') throw new AuthError('missing bearer token');
  return token;
}

module.exports = {
  AuthError,
  ForbiddenError,
  normalizeIssuer,
  createTokenVerifier,
  extractRoles,
  isAdmin,
  bearerToken,
  DEFAULT_JWKS_URI,
};"}

