  return {
    prompt: prompt.trim(),
    options: options.slice(),
    correctAnswer: formatFraction(parsed),
  };
}

/**
 * Build the question-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.repository]  repository instance (pg or in-memory)
 * @param {object} [deps.search]      search adapter instance
 * @param {object} [deps.logger]      optional logger (default: console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const repository = deps.repository || new InMemoryQuestionRepository();
  const search = deps.search || new QuestionSearch(null);
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  // Health for orchestration/tests.
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'question-service' });
  });

  // List questions (admin UI needs this; no pagination requirement).
  app.get('/questions', async (req, res) => {
    try {
      const questions = await repository.list();
      res.status(200).json({ questions });
    } catch (err) {
      log.error('list questions failed', err.message);
      res.status(500).json({ error: 'internal_error' });
    }
  });

  // Get a single question by id.
  app.get('/questions/:id', async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'invalid_id' });
      }
      const q = await repository.get(id);
      if (!q) return res.status(404).json({ error: 'not_found' });
      return res.status(200).json(q);
    } catch (err) {
      log.error('get question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  // Search questions via Elasticsearch (real client when configured).
  app.get('/questions/search', async (req, res) => {
    try {
      const query = typeof req.query.q === 'string' ? req.query.q : '';
      const results = await search.search(query);
      res.status(200).json({ questions: results });
    } catch (err) {
      log.error('search questions failed', err.message);
      res.status(500).json({ error: 'search_error' });
    }
  });

  // Validate-only endpoint (used by admin service before persisting).
  app.post('/questions/validate', (req, res) => {
    try {
      const normalized = validateQuestionPayload(req.body);
      res.status(200).json({ valid: true, question: normalized });
    } catch (err) {
      if (err instanceof ValidationError) {
        return res.status(400).json({ error: err.message });
      }
      log.error('validate failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  // Create a question.
  app.post('/questions', async (req, res) => {
    try {
      const normalized = validateQuestionPayload(req.body);
      const created = await repository.create(normalized);
      await search.index(created).catch((err) => {
        // Search indexing is best-effort; persistence keeps source of truth.
        log.warn('search index failed (non-fatal)', err.message);
      });
      res.status(201).json(created);
    } catch (err) {
      if (err instanceof ValidationError) {
        return res.status(400).json({ error: err.message });
      }
      log.error('create question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  // Delete a question (idempotent 404 when missing).
  app.delete('/questions/:id', async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'invalid_id' });
      }
      const removed = await repository.remove(id);
      if (!removed) return res.status(404).json({ error: 'not_found' });
      await search.remove(id).catch((err) => log.warn('search remove failed', err.message));
      return res.status(204).end();
    } catch (err) {
      log.error('delete question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

/**
 * Build production dependencies: a PostgreSQL-backed repository and a real
 * Elasticsearch client + search adapter. Returns an object suitable for
 * buildApp().
 */
function buildProductionDeps() {
  const repository = new PgQuestionRepository(process.env.DATABASE_URL);

  let search = new QuestionSearch(null);
  if (process.env.ELASTICSEARCH_URL) {
    const client = new Client({ node: process.env.ELASTICSEARCH_URL });
    search = new QuestionSearch(client);
  }
  return { repository, search };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  // Boot with production deps; when Postgres/ES are absent the repository
  // constructor does not connect eagerly, so the HTTP listener still starts.
  const { repository, search } = buildProductionDeps();
  const app = buildApp({ repository, search });
  const server = app.listen(PORT, () => {
    console.log(`question-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  validateQuestionPayload,
  buildProductionDeps,
  ValidationError,
};

'use strict';

/**
 * Question repository — persistence layer for the question service.
 *
 * Provides two implementations behind a common interface:
 *   - PgQuestionRepository: PostgreSQL 16 source of truth (schema
 *     sql/migrations/001_schema.sql). Questions are stored with options as a
 *     JSONB array and correct_answer as a canonical single-fraction TEXT.
 *   - InMemoryQuestionRepository: dependency-injection test adapter used by the
 *     unit tests so the default `npm test` runs without live PostgreSQL.
 *
 * Exposes the shared ValidationError so the index.js route factory can branch
 * 400-vs-500 error handling without duplicating the error type.
 *
 * Repository interface (consumed by packages/question-service/src/index.js):
 *   list()                 -> Promise<Array<{id,prompt,options,correctAnswer}>>
 *   get(id)                -> Promise<question|null>
 *   create({prompt,options,correctAnswer}) -> Promise<question-with-id>
 *   remove(id)             -> Promise<boolean>  (true when a row was deleted)
 */

const { Client } = require('pg');

/** Validation error thrown for malformed question payloads (=> HTTP 400). */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

/** Shared row -> API shape mapping (snake_case column -> camelCase API key). */
function rowToQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: Array.isArray(row.options) ? row.options.slice() : [],
    correctAnswer: row.correct_answer,
  };
}

/**
 * PostgreSQL-backed question repository.
 *
 * Constructed lazily: the pg Client only opens a connection on first use so the
 * HTTP listener can still boot when Postgres is momentarily unreachable
 * (bounded downstream timeouts are layered on top by the service).
 */
class PgQuestionRepository {
  constructor(connectionString) {
    this.client = new Client({ connectionString });
  }

  async _ensureConnected() {
    if (!this._connected) {
      await this.client.connect();
      this._connected = true;
    }
  }

  async list() {
    await this._ensureConnected();
    const res = await this.client.query(
      'SELECT id, prompt, options, correct_answer FROM questions ORDER BY id ASC',
    );
    return res.rows.map(rowToQuestion);
  }

  async get(id) {
    await this._ensureConnected();
    const res = await this.client.query(
      'SELECT id, prompt, options, correct_answer FROM questions WHERE id = $1',
      [id],
    );
    return res.rows.length ? rowToQuestion(res.rows[0]) : null;
  }

  async create({ prompt, options, correctAnswer }) {
    await this._ensureConnected();
    const res = await this.client.query(
      `INSERT INTO questions (prompt, options, correct_answer)
       VALUES ($1, $2, $3)
       RETURNING id, prompt, options, correct_answer`,
      [prompt, JSON.stringify(options || []), correctAnswer],
    );
    return rowToQuestion(res.rows[0]);
  }

  async remove(id) {
    await this._ensureConnected();
    const res = await this.client.query('DELETE FROM questions WHERE id = $1', [id]);
    return res.rowCount > 0;
  }

  async close() {
    if (this._connected) {
      await this.client.end();
      this._connected = false;
    }
  }
}

/**
 * In-memory repository for unit tests. Backed by a plain Map with an
 * auto-incrementing id counter so tests exercise real route/validation logic
 * without external infrastructure.
 */
class InMemoryQuestionRepository {
  constructor() {
    this.rows = new Map();
    this.nextId = 1;
  }

  async list() {
    return Array.from(this.rows.values()).map(rowToQuestion);
  }

  async get(id) {
    const row = this.rows.get(id);
    return row ? rowToQuestion(row) : null;
  }

  async create({ prompt, options, correctAnswer }) {
    const id = this.nextId++;
    const row = {
      id,
      prompt,
      options: Array.isArray(options) ? options.slice() : [],
      correct_answer: correctAnswer,
    };
    this.rows.set(id, row);
    return rowToQuestion(row);
  }

  async remove(id) {
    return this.rows.delete(id);
  }

  async close() {
    this.rows.clear();
  }
}

module.exports = {
  PgQuestionRepository,
  InMemoryQuestionRepository,
  ValidationError,
  rowToQuestion,
};

'use strict';

/**
 * User service — OIDC identity resolution and authorization for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 10-14, 37-44):
 *   - Validate a Bearer OIDC access token (issuer/audience/JWKS signature) via
 *     the shared `src/shared/oidc.js` helpers.
 *   - Map the verified `sub` claim to a numeric internal user id using the
 *     `users` table (UNIQUE subject) — creating the user lazily on first sight
 *     so authenticated players always have an owner id for game authorization.
 *   - Expose owner/admin authorization helpers consumed by the game-service and
 *     admin-service (the gateway fans out requests; this service is the single
 *     place that resolves JWT `sub` -> `users.id`).
 *
 * OIDC environment contract (space-fractions.md line 40):
 *   - OIDC_ISSUER  public issuer origin.
 *   - OIDC_JWKS_URI internal-certificates endpoint (default http://keycloak:8080/...).
 *   - OIDC_AUDIENCE expected audience (default "account").
 *   - OIDC_ADMIN_ROLE role name conferring administrator privileges (default "admin").
 *
 * The service boots its HTTP listener even when PostgreSQL is unreachable: the
 * pg `Client` connects lazily, and unit tests inject an in-memory repository.
 */

const express = require('express');
const { Client } = require('pg');

const oidc = require('../../shared/oidc');

const PORT = Number(process.env.USER_SERVICE_PORT || process.env.PORT || 3003);

/** Validation/authorization error helper (mirrors shared AuthError semantics). */
class UserServiceError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'UserServiceError';
    this.status = status;
  }
}

/**
 * Repository interface:
 *   findOrCreateBySubject(subject, profile) -> Promise<User>
 *   findBySubject(subject)                 -> Promise<User|null>
 *   findById(id)                           -> Promise<User|null>
 * where User = { id, subject, profile, roles }.
 */

/** PostgreSQL-backed user repository (source of truth: sql/migrations/001_schema.sql). */
class PgUserRepository {
  constructor(connectionString) {
    this.client = new Client({ connectionString });
  }

  async _ensureConnected() {
    if (!this._connected) {
      await this.client.connect();
      this._connected = true;
    }
  }

  async findOrCreateBySubject(subject, profile = '') {
    await this._ensureConnected();
    await this.client.query('BEGIN');
    try {
      // Lock-free upsert on the UNIQUE(subject) index; profile defaults applied
      // at creation but not overwritten on re-sight (name ownership preserved).
      const res = await this.client.query(
        `INSERT INTO users (subject, profile)
         VALUES ($1, $2)
         ON CONFLICT (subject) DO UPDATE SET updated_at = now()
         RETURNING id, subject, profile, roles`,
        [subject, profile],
      );
      await this.client.query('COMMIT');
      return rowToUser(res.rows[0]);
    } catch (err) {
      await this.client.query('ROLLBACK');
      throw err;
    }
  }

  async findBySubject(subject) {
    await this._ensureConnected();
    const res = await this.client.query(
      'SELECT id, subject, profile, roles FROM users WHERE subject = $1',
      [subject],
    );
    return res.rows.length ? rowToUser(res.rows[0]) : null;
  }

  async findById(id) {
    await this._ensureConnected();
    const res = await this.client.query(
      'SELECT id, subject, profile, roles FROM users WHERE id = $1',
      [id],
    );
    return res.rows.length ? rowToUser(res.rows[0]) : null;
  }

  async close() {
    if (this._connected) {
      await this.client.end();
      this._connected = false;
    }
  }
}

/** In-memory adapter for unit tests (no live PostgreSQL required). */
class InMemoryUserRepository {
  constructor() {
    this.rows = new Map(); // id -> User
    this.bySubject = new Map(); // subject -> id
    this.nextId = 1;
  }

  async findOrCreateBySubject(subject, profile = '') {
    const existing = await this.findBySubject(subject);
    if (existing) return existing;
    const id = this.nextId++;
    const user = { id, subject, profile, roles: [] };
    this.rows.set(id, user);
    this.bySubject.set(subject, id);
    return user;
  }

  async findBySubject(subject) {
    const id = this.bySubject.get(subject);
    return id ? this.rows.get(id) : null;
  }

  async findById(id) {
    return this.rows.get(id) || null;
  }

  async close() {
    this.rows.clear();
    this.bySubject.clear();
  }
}

function rowToUser(row) {
  return {
    id: row.id,
    subject: row.subject,
    profile: row.profile,
    roles: Array.isArray(row.roles) ? row.roles.slice() : [],
  };
}

/**
 * Resolve the authenticated identity from an Authorization header.
 *
 * Verifies the token, extracts `sub` and roles, and maps `sub` to the numeric
 * internal user id via the repository (lazily creating the user). Returns
 * { id, subject, profile, roles } on success.
 *
 * @param {object} repo       user repository
 * @param {object} verifier   OIDC token verifier ({ verify })
 * @param {string|undefined} authorizationHeader
 * @param {string} [profile]  profile name to persist on first sight
 * @returns {Promise<object>}
 */
async function authenticate(repo, verifier, authorizationHeader, profile) {
  const token = oidc.bearerToken(authorizationHeader);
  const payload = await verifier.verify(token);
  const sub = payload.sub;
  const roles = oidc.extractRoles(payload);
  const existing = await repo.findBySubject(sub);
  const principal = existing || (await repo.findOrCreateBySubject(sub, profile || payload.preferred_username || sub));
  return {
    id: principal.id,
    subject: sub,
    profile: principal.profile,
    roles,
  };
}

/**
 * Build the user-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.repository] user repository (pg or in-memory)
 * @param {object} [deps.verifier]   OIDC token verifier ({ verify })
 * @param {object} [deps.logger]     logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const repository = deps.repository || new InMemoryUserRepository();
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  // Health for orchestration/tests.
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'user-service' });
  });

  /**
   * Authenticate the bearer token and return the resolved principal. Used by
   * the gateway's downstream routing and by tests for owner/admin checks.
   *   200 {id, subject, profile, roles}
   *   401 missing/invalid credentials
   */
  app.post('/auth/verify', async (req, res) => {
    try {
      const principal = await authenticate(repository, verifier, req.headers.authorization);
      res.status(200).json(principal);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      log.error('auth verify failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Resolve a verified subject to its internal numeric id (no side effects when
   * the user already exists; lazily creates when absent). Mirrors /auth/verify
   * but makes the id-mapping contract explicit for the async service.
   *   200 {id, subject, profile}
   *   401 missing/invalid credentials
   */
  app.get('/users/me', async (req, res) => {
    try {
      const principal = await authenticate(repository, verifier, req.headers.authorization);
      res.status(200).json({
        id: principal.id,
        subject: principal.subject,
        profile: principal.profile,
        roles: principal.roles,
      });
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      log.error('users/me failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Fetch a user by numeric internal id (used by game/admin services to check
   * ownership without re-walking the token). No authorization requirement for a
   * read of profile metadata; secrets are never exposed.
   */
  app.get('/users/:id', async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'invalid_id' });
      }
      const user = await repository.findById(id);
      if (!user) return res.status(404).json({ error: 'not_found' });
      return res.status(200).json(user);
    } catch (err) {
      log.error('get user failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

function buildProductionDeps() {
  const repository = new PgUserRepository(process.env.DATABASE_URL);
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  return { repository, verifier };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const { repository, verifier } = buildProductionDeps();
  const app = buildApp({ repository, verifier });
  const server = app.listen(PORT, () => {
    console.log(`user-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
  authenticate,
  PgUserRepository,
  InMemoryUserRepository,
  UserServiceError,
};

'use strict';

/**
 * Shared domain utilities for the Space Fractions system.
 *
 * Exact rational arithmetic for sixth-grade fraction answers. No external
 * services and no floating point: fractions are represented as normalized
 * { numerator, denominator } pairs of arbitrary-precision-ish integers
 * (Node's number type, but arithmetic kept exact by normalizing before and
 * after each operation).
 *
 * Grammar (implementation-defined, origin=assumption):
 *   - integer:            "3", "-3"
 *   - simple fraction:    "1/2", "-3/4", "5/-6" (sign may prefix numerator
 *                         or denominator)
 *   - mixed number:       "1 1/2", "-2 3/4"
 *
 * parseFraction returns an invalid sentinel (null) rather than throwing so
 * callers can distinguish a 400 (malformed fraction) from other errors.
 */

const MATH_ERROR = 'Division by zero';

/**
 * Greatest common divisor (Euclid, non-negative operands).
 * @param {number} a
 * @param {number} b
 * @returns {number}
 */
function gcd(a, b) {
  let x = Math.abs(a);
  let y = Math.abs(b);
  while (y !== 0) {
    const t = y;
    y = x % y;
    x = t;
  }
  return x === 0 ? 1 : x;
}

/**
 * Reduce a fraction to lowest terms with a positive denominator, carrying the
 * sign on the numerator. Returns null if the denominator is zero.
 *
 * @param {number} numerator
 * @param {number} denominator
 * @returns {{numerator:number, denominator:number}|null}
 */
function normalize(numerator, denominator) {
  if (denominator === 0) return null;
  let n = numerator;
  let d = denominator;
  if (d < 0) {
    n = -n;
    d = -d;
  }
  const g = gcd(n, d);
  return { numerator: n / g, denominator: d / g };
}

/**
 * Parse a fraction string into a normalized exact rational pair.
 * Accepts integers, simple fractions and mixed numbers.
 *
 * @param {string} input
 * @returns {{numerator:number, denominator:number}|null} null when invalid
 */
function parseFraction(input) {
  if (typeof input !== 'string') return null;
  const text = input.trim();
  if (text === '') return null;

  const INVALID = null;
  const INT = /^[+-]?\d+$/;
  const FRAC = /^([+-]?\d+)\/([+-]?\d+)$/;
  const MIXED = /^([+-]?\d+)\s+(\d+)\/(\d+)$/;

  if (INT.test(text)) {
    return normalize(Number(text), 1);
  }

  const frac = FRAC.exec(text);
  if (frac) {
    return normalize(Number(frac[1]), Number(frac[2]));
  }

  const mixed = MIXED.exec(text);
  if (mixed) {
    const whole = Number(mixed[1]);
    const num = Number(mixed[2]);
    const den = Number(mixed[3]);
    if (den === 0) return INVALID;
    const sign = whole < 0 ? -1 : 1;
    const absWhole = Math.abs(whole);
    return normalize(sign * (absWhole * den + num), den);
  }

  return INVALID;
}

/**
 * Format a normalized fraction pair as a canonical string ("a/b", or "a" for a
 * unit denominator). Returns null for an invalid pair (zero denominator).
 *
 * @param {{numerator:number, denominator:number}} f
 * @returns {string|null}
 */
function formatFraction(f) {
  if (!f || typeof f !== 'object') return null;
  const n = normalize(f.numerator, f.denominator);
  if (!n) return null;
  if (n.denominator === 1) return String(n.numerator);
  return `${n.numerator}/${n.denominator}`;
}

/**
 * Exact equality of two fractions. Accepts either { numerator, denominator }
 * objects or fraction strings ("1/2" equals "2/4").
 *
 * @param {object|string} a
 * @param {object|string} b
 * @returns {boolean}
 */
function equals(a, b) {
  const fa = toFraction(a);
  const fb = toFraction(b);
  if (!fa || !fb) return false;
  return fa.numerator === fb.numerator && fa.denominator === fb.denominator;
}

/**
 * Exact comparison. Returns -1, 0, or 1 (a < b, a === b, a > b).
 *
 * @param {object|string} a
 * @param {object|string} b
 * @returns {number}
 */
function compare(a, b) {
  const fa = toFraction(a);
  const fb = toFraction(b);
  if (!fa || !fb) return NaN;
  const lhs = fa.numerator * fb.denominator;
  const rhs = fb.numerator * fa.denominator;
  return lhs < rhs ? -1 : lhs > rhs ? 1 : 0;
}

/**
 * Exact addition. Returns a normalized pair or null on invalid input.
 *
 * @param {object|string} a
 * @param {object|string} b
 * @returns {{numerator:number, denominator:number}|null}
 */
function add(a, b) {
  const fa = toFraction(a);
  const fb = toFraction(b);
  if (!fa || !fb) return null;
  return normalize(
    fa.numerator * fb.denominator + fb.numerator * fa.denominator,
    fa.denominator * fb.denominator,
  );
}

/**
 * Exact subtraction (a - b). Returns a normalized pair or null.
 *
 * @param {object|string} a
 * @param {object|string} b
 * @returns {{numerator:number, denominator:number}|null}
 */
function subtract(a, b) {
  const fb = toFraction(b);
  if (!fb) return null;
  return add(a, { numerator: -fb.numerator, denominator: fb.denominator });
}

/**
 * Exact multiplication. Returns a normalized pair or null.
 *
 * @param {object|string} a
 * @param {object|string} b
 * @returns {{numerator:number, denominator:number}|null}
 */
function multiply(a, b) {
  const fa = toFraction(a);
  const fb = toFraction(b);
  if (!fa || !fb) return null;
  return normalize(fa.numerator * fb.numerator, fa.denominator * fb.denominator);
