    correct: correct.numerator === submitted.numerator && correct.denominator === submitted.denominator,
  };
}

module.exports = {
  MATH_ERROR,
  gcd,
  normalize,
  parseFraction,
  formatFraction,
  toFraction,
  equals,
  compare,
  add,
  subtract,
  multiply,
  divide,
  validateAnswer,
};

