'use strict';

/**
 * Space Fractions gateway — public edge (container port 3000).
 *
 * Responsibilities (space-fractions.md lines 15-24, 30-31):
 *   - GET /health -> 200 (orchestration/liveness probe).
 *   - Serve the plain browser UI (HTML/CSS/JS, no bundler) at "/".
 *   - Reverse-proxy authenticated API requests to the downstream services
 *     (game-service, question-service, user-service, admin-service), forwarding
 *     the Bearer OIDC access token verbatim so each service enforces its own
 *     authorization boundary.
 *   - Bounded downstream timeouts + error handling: a slow/unreachable service
 *     yields a 504/502, never an open socket.
 *   - Publish Prometheus metrics on GET /metrics.
 *   - Original GET /play backwards compatibility -> creates a practice game and
 *     returns { gameId } (Architecture_Documentation.md line 105).
 *
 * The gateway holds no domain state and performs no scoring/authorization of
 * its own. It computes the public browser origin from PUBLIC_ORIGIN (never a
 * hard-coded host:port) so Keycloak redirects work across remapped test ports.
 *
 * A reverse proxy with bounded timeouts is implemented on Node's built-in
 * `http` + global `fetch` (bounded via AbortController) rather than adding a
 * third-party proxy, keeping the runtime surface small and unit-testable —
 * injectable `routes`/`request` dependencies (see `buildApp`).
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = Number(process.env.PORT || 3000);

/** Per-downstream bounded timeout (ms) for API fan-out. */
const DOWNSTREAM_TIMEOUT_MS = Number(process.env.GATEWAY_TIMEOUT_MS || 10000);

/** Maximum forwarded request body (aligns with each service's `1mb` JSON limit). */
const MAX_BODY_BYTES = 1024 * 1024;

/** Default public-facing origin used for browser redirects/links. */
function publicOrigin() {
  return process.env.PUBLIC_ORIGIN || `http://localhost:${PORT}`;
}

/**
 * Read the static UI directory once (memoized). Returns a map of
 * relative-path -> { contentType, body } for every file under `public/`.
 */
function loadStaticAssets(staticDir) {
  const dir = staticDir || path.join(__dirname, '..', 'public');
  const assets = new Map();
  const walkAndRead = (base, relative) => {
    const entries = fs.readdirSync(base, { withFileTypes: true });
    for (const entry of entries) {
      const abs = path.join(base, entry.name);
      const rel = relative ? `${relative}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        walkAndRead(abs, rel);
      } else {
        assets.set(`/${rel}`, {
          contentType: contentTypeFor(rel),
          body: fs.readFileSync(abs),
        });
      }
    }
  };
  walkAndRead(dir, '');
  return assets;
}

function contentTypeFor(file) {
  if (file.endsWith('.html')) return 'text/html; charset=utf-8';
  if (file.endsWith('.css')) return 'text/css; charset=utf-8';
  if (file.endsWith('.js')) return 'application/javascript; charset=utf-8';
  if (file.endsWith('.json')) return 'application/json; charset=utf-8';
  if (file.endsWith('.svg')) return 'image/svg+xml';
  return 'application/octet-stream';
}

/**
 * Lightweight metrics registry (no external client required for the core
 * counters). Exposed as the standard Prometheus text format. Counters:
 *   http_requests_total{method,path,status}
 *   downstream_requests_total{service,status}
 *   downstream_timeouts_total{service}
 */
function createMetrics() {
  const counters = new Map();
  const inc = (name, labels) => {
    const key = `${name}{${Object.entries(labels).map(([k, v]) => `${k}="${v}"`).join(',')}}`;
    counters.set(key, (counters.get(key) || 0) + 1);
  };
  return {
    inc,
    render() {
      const lines = [];
      for (const [key, value] of counters.entries()) {
        lines.push(`${key} ${value}`);
      }
      return `${lines.join('\n')}\n`;
    },
  };
}

/**
 * Message shape expected from a downstream service URL: either a base URL
 * string, or an object { base, service } where `service` is the metrics label.
 */
function resolveTarget(entry) {
  if (typeof entry === 'string') return { base: entry, service: entry };
  return { base: entry.base, service: entry.service };
}

/**
 * Build the gateway HTTP request handler.
 *
 * @param {object} [deps]
 * @param {Map<string,object>} [deps.assets]  static asset map (loadStaticAssets)
 * @param {object}            [deps.routes]  { prefix: string|{base,service} }
 *   mapping URL prefixes to downstream base URLs (e.g. { '/api/games': 'http://game-service:3001' }).
 * @param {function}          [deps.fetch]   fetch implementation (default global fetch)
 * @param {object}            [deps.metrics] metrics registry (default createMetrics())
 * @param {object}            [deps.logger]  logger (default console)
 * @returns {http.RequestListener}
 */
function buildApp(deps = {}) {
  const assets = deps.assets || loadStaticAssets();
  const routes = deps.routes || defaultRoutes();
  const fetchImpl = deps.fetch || globalThis.fetch;
  const metrics = deps.metrics || createMetrics();
  const log = deps.logger || console;
  const origin = deps.publicOrigin || publicOrigin();

  async function readBody(req) {
    const chunks = [];
    let size = 0;
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        const err = new Error('request body too large');
        err.status = 413;
        throw err;
      }
      chunks.push(chunk);
    }
    return Buffer.concat(chunks);
  }

  function respond(res, status, headers, body) {
    res.writeHead(status, headers);
    res.end(body);
  }

  function json(res, status, obj) {
    respond(
      res,
      status,
      { 'content-type': 'application/json; charset=utf-8' },
      JSON.stringify(obj),
    );
  }

  /**
   * Forward an incoming request to the selected downstream target with a
   * bounded timeout. Returns { status, headers, body } on success; throws on
   * timeout (504) or refusal (502).
   */
  async function forward(req, target, body) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), DOWNSTREAM_TIMEOUT_MS);
    const url = new URL(req.url, target.base);
    try {
      const upstream = await fetchImpl(url.toString(), {
        method: req.method,
        headers: {
          'content-type': req.headers['content-type'] || 'application/json',
          // Forward the Bearer token verbatim so downstream services authorize.
          ...(req.headers.authorization
            ? { authorization: req.headers.authorization }
            : {}),
          accept: 'application/json',
        },
        body: req.method === 'GET' || req.method === 'HEAD' ? undefined : body,
        signal: controller.signal,
      });
      const resBody = await upstream.arrayBuffer();
      return {
        status: upstream.status,
        headers: upstream.headers,
        body: Buffer.from(resBody),
      };
    } catch (err) {
      if (err && err.name === 'AbortError') {
        const e = new Error(`downstream timeout: ${target.service}`);
        e.status = 504;
        throw e;
      }
      const e = new Error(`downstream unavailable: ${target.service}`);
      e.status = 502;
      throw e;
    } finally {
      clearTimeout(timer);
    }
  }

  function forwardableHeaders(headers) {
    const out = { 'content-type': 'application/json; charset=utf-8' };
    for (const key of ['content-type', 'cache-control', 'etag']) {
      if (headers && headers.get && headers.get(key)) out[key] = headers.get(key);
    }
    return out;
  }

  async function handle(req, res) {
    const parsed = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const pathname = parsed.pathname;
    const start = Date.now();

    try {
      // Liveness/readiness.
      if (pathname === '/health') {
        metrics.inc('http_requests_total', { method: 'GET', path: '/health', status: 200 });
        return json(res, 200, { status: 'ok', service: 'gateway' });
      }

      // Prometheus scrape endpoint.
      if (pathname === '/metrics') {
        metrics.inc('http_requests_total', { method: 'GET', path: '/metrics', status: 200 });
        return respond(res, 200, { 'content-type': 'text/plain; version=0.0.4; charset=utf-8' }, metrics.render());
      }

      // Original GET /play compatibility -> create a practice game, return gameId.
      if (pathname === '/play' && req.method === 'GET') {
        const gameTarget = resolveTarget(routes['/api/games']);
        const body = Buffer.from('{}');
        const { status, headers, body: resBody } = await forward(
          { ...req, url: '/api/games', method: 'POST' },
          gameTarget,
          body,
        );
        let gameId = null;
        try {
          const created = JSON.parse(resBody.toString('utf8'));
          gameId = created.id;
        } catch {
          /* downstream already errored */
        }
        const finalStatus = status < 400 && gameId ? 200 : status;
        metrics.inc('downstream_requests_total', { service: gameTarget.service, status });
        metrics.inc('http_requests_total', { method: 'GET', path: '/play', status: finalStatus });
        if (gameId) return json(res, finalStatus, { gameId });
        return respond(res, status, forwardableHeaders(headers), resBody);
      }

      // Static UI (served at "/", plus assets referenced by index.html).
      if (req.method === 'GET' || req.method === 'HEAD') {
        const assetPath = pathname === '/' ? '/index.html' : pathname;
        const asset = assets.get(assetPath);
        if (asset) {
          metrics.inc('http_requests_total', { method: req.method, path: pathname, status: 200 });
          const headers = { 'content-type': asset.contentType, 'cache-control': 'no-cache' };
          return respond(res, 200, headers, req.method === 'HEAD' ? undefined : asset.body);
        }
      }

      // API fan-out: longest matching prefix.
      const matching = Object.keys(routes)
        .filter((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`))
        .sort((a, b) => b.length - a.length)[0];
      if (matching) {
        const target = resolveTarget(routes[matching]);
        const body = req.method === 'GET' || req.method === 'HEAD' ? undefined : await readBody(req);
        const { status, headers, body: resBody } = await forward(req, target, body);
        metrics.inc('downstream_requests_total', { service: target.service, status });
        metrics.inc('http_requests_total', { method: req.method, path: pathname, status });
        return respond(res, status, forwardableHeaders(headers), resBody);
      }

      metrics.inc('http_requests_total', { method: req.method, path: pathname, status: 404 });
      return json(res, 404, { error: 'not_found' });
    } catch (err) {
      const status = err && err.status ? err.status : 500;
      log.error(`gateway error on ${req.method} ${pathname}`, err.message);
      metrics.inc('http_requests_total', { method: req.method, path: pathname, status });
      if (status === 504) {
        const serviceLabel = (err.service || 'unknown');
        metrics.inc('downstream_timeouts_total', { service: serviceLabel });
      }
      return json(res, status, { error: status === 504 ? 'gateway_timeout' : status === 502 ? 'bad_gateway' : 'internal_error' });
    }
  }

  return handle;
}

/** Default downstream routes resolved from env with container defaults. */
function defaultRoutes() {
  return {
    '/api/games': process.env.GAME_SERVICE_URL || 'http://game-service:3001',
    '/api/questions': process.env.QUESTION_SERVICE_URL || 'http://question-service:3002',
    '/api/users': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/users': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/auth': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/api/admin': process.env.ADMIN_SERVICE_URL || 'http://admin-service:3004',
  };
}

/**
 * Start the gateway HTTP listener (kept alive until SIGTERM/SIGINT).
 * The listener stays alive independently of downstream availability, so the
 * startup probe passes even before backing services are ready.
 */
function startServer(app, port) {
  const server = http.createServer(app);
  server.listen(port, () => {
    console.log(`gateway listening on :${port}`);
  });
  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
  return server;
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  startServer(buildApp(process.env.GATEWAY_STATIC_DIR ? {
    assets: loadStaticAssets(process.env.GATEWAY_STATIC_DIR),
  } : {}), PORT);
}

module.exports = {
  buildApp,
  loadStaticAssets,
  createMetrics,
  defaultRoutes,
  startServer,
  publicOrigin,
  contentTypeFor,
};

'use strict';

/**
 * Admin service — authenticated administrator question CRUD for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 15-16; Architecture_View.md
 * lines 3-14 — the "Update Questions" admin use case):
 *   - Authenticate a Bearer OIDC access token and authorize the ADMIN role.
 *   - POST   /api/admin/questions     -> 201 {id,prompt,options,correctAnswer}
 *   - GET    /api/admin/questions     -> 200 {questions:[...]}
 *   - DELETE /api/admin/questions/:id -> 200 (or 204), 404 when id missing.
 *   - Normal (non-admin) users receive 403; missing/invalid credentials 401.
 *
 * The admin service is the authorization boundary. It reuses:
 *   - `src/shared/oidc.js`            for token verification and admin-role check.
 *   - `packages/user-service`         `authenticate()` to map verified `sub` to a
 *     numeric internal user id (single home for JWT sub -> users.id resolution).
 *   - `packages/question-service`      `validateQuestionPayload()` + repository +
 *     `QuestionSearch` so question writes and search indexing stay consistent
 *     with the question service (correctAnswer validated as a single exact
 *     fraction; options array of strings).
 *
 * OIDC environment contract (space-fractions.md line 40):
 *   - OIDC_ISSUER/OIDC_AUDIENCE/OIDC_JWKS_URI/OIDC_ADMIN_ROLE (default "admin").
 *
 * Like the question/user services, the pg `Client` connects lazily so the HTTP
 * listener still boots when PostgreSQL is temporarily unreachable. Unit tests
 * inject in-memory repositories and a scripted token verifier.
 */

const express = require('express');

const oidc = require('../../shared/oidc');
const {
  validateQuestionPayload,
  ValidationError: QuestionValidationError,
} = require('../../question-service/src/index');
const {
  InMemoryQuestionRepository,
  PgQuestionRepository,
} = require('../../question-service/src/repository');
const { QuestionSearch } = require('../../question-service/src/search');
const {
  authenticate,
  InMemoryUserRepository,
  PgUserRepository,
} = require('../../user-service/src/index');

const PORT = Number(process.env.ADMIN_SERVICE_PORT || process.env.PORT || 3004);
const ADMIN_ROLE = () => process.env.OIDC_ADMIN_ROLE || 'admin';

/**
 * Build the admin-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.userRepository]  user repository (pg or in-memory)
 * @param {object} [deps.verifier]        OIDC token verifier ({ verify })
 * @param {object} [deps.questionRepository] question repository (pg or in-memory)
 * @param {object} [deps.search]          QuestionSearch adapter
 * @param {object} [deps.logger]          logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const userRepository = deps.userRepository || new InMemoryUserRepository();
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const questionRepository =
    deps.questionRepository || new InMemoryQuestionRepository();
  const search = deps.search || new QuestionSearch(null);
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  // Health for orchestration/tests.
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'admin-service' });
  });

  /**
   * Resolve the authenticated principal and enforce the administrator role.
   * Throws UserServiceError for JSON-error mapping is avoided here; instead we
   * branch inside handlers via the thrown error's `name`/`status`. `authenticate`
   * throws a shared oidc.AuthError (401) on missing/invalid credentials.
   *
   * Returns { id, subject, profile, roles } for an admin, otherwise throws a
   * 403 error object we construct locally.
   */
  async function requireAdmin(req) {
    const principal = await authenticate(
      userRepository,
      verifier,
      req.headers.authorization,
    );
    if (!oidc.isAdmin({ realm_access: { roles: principal.roles } }, ADMIN_ROLE())) {
      const err = new Error('forbidden');
      err.name = 'ForbiddenError';
      err.status = 403;
      throw err;
    }
    return principal;
  }

  /**
   * List all questions (admin view). Contract: { questions: [...] }.
   *   200 on success; 401 missing/invalid credentials; 403 non-admin.
   */
  app.get('/api/admin/questions', async (req, res) => {
    try {
      await requireAdmin(req);
      const questions = await questionRepository.list();
      res.status(200).json({ questions });
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      if (err && err.name === 'ForbiddenError') {
        return res.status(403).json({ error: 'forbidden' });
      }
      log.error('list admin questions failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Create a question. Contract: 201 {id,prompt,options,correctAnswer}.
   * Malformed payload (bad prompt/options/fraction) -> 400; 401/403 as above.
   */
  app.post('/api/admin/questions', async (req, res) => {
    try {
      await requireAdmin(req);
      const normalized = validateQuestionPayload(req.body);
      const created = await questionRepository.create(normalized);
      await search.index(created).catch((indexErr) => {
        // Search indexing is best-effort; PostgreSQL remains the source of truth.
        log.warn('search index failed (non-fatal)', indexErr.message);
      });
      res.status(201).json(created);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      if (err && err.name === 'ForbiddenError') {
        return res.status(403).json({ error: 'forbidden' });
      }
      if (err instanceof QuestionValidationError) {
        return res.status(400).json({ error: err.message });
      }
      log.error('create admin question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Delete a question by id. Contract: 200 (JSON ack) or 204 on success, 404 when
   * the id does not exist, 400 on a malformed id, 401/403 as above.
   */
  app.delete('/api/admin/questions/:id', async (req, res) => {
    try {
      await requireAdmin(req);
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'invalid_id' });
      }
      const removed = await questionRepository.remove(id);
      if (!removed) return res.status(404).json({ error: 'not_found' });
      await search.remove(id).catch((removeErr) =>
        log.warn('search remove failed (non-fatal)', removeErr.message),
      );
      return res.status(200).json({ deleted: id });
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      if (err && err.name === 'ForbiddenError') {
        return res.status(403).json({ error: 'forbidden' });
      }
      log.error('delete admin question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

/**
 * Build production dependencies: PostgreSQL-backed user + question repositories,
 * a real OIDC verifier, and an Elasticsearch-backed QuestionSearch when
 * ELASTICSEARCH_URL is configured.
 */
function buildProductionDeps() {
  const userRepository = new PgUserRepository(process.env.DATABASE_URL);
  const questionRepository = new PgQuestionRepository(process.env.DATABASE_URL);
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  const { Client } = require('@elastic/elasticsearch');
  const search = process.env.ELASTICSEARCH_URL
    ? new QuestionSearch(new Client({ node: process.env.ELASTICSEARCH_URL }))
    : new QuestionSearch(null);
  return { userRepository, questionRepository, verifier, search };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const { userRepository, questionRepository, verifier, search } = buildProductionDeps();
  const app = buildApp({ userRepository, questionRepository, verifier, search });
  const server = app.listen(PORT, () => {
    console.log(`admin-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
};

'use strict';

/**
 * Shared OIDC helpers for Space Fractions.
 *
 * Implements the OIDC contract from space-fractions.md lines 10-14 and 37-44:
 *   - Validate a Bearer OIDC access token: issuer, audience and JWKS-signature.
 *   - Map the verified `sub` claim to the numeric internal user id (done in the
 *     user-service; this module only produces the verified claims/roles).
 *   - Expose an admin-role check consumed by the admin-service.
 *
 * Environment contract (space-fractions.md line 40):
 *   - OIDC_ISSUER   public issuer origin (validated exactly against the `iss` claim).
 *   - OIDC_JWKS_URI internal certificates endpoint
 *                    (default http://keycloak:8080/realms/space-fractions/protocol/openid-connect/certs).
 *   - OIDC_AUDIENCE expected audience (default "account").
 *   - OIDC_ADMIN_ROLE role name conferring administrator privileges (default "admin").
 *
 * This module is dependency-free: JWT verification uses Node's built-in
 * `crypto` (RS256/RS384/RS512/ES256) and `fetch` for JWKS. It is therefore
 * unit-testable without a live identity provider by injecting a JWKS/verify
 * strategy via `createTokenVerifier` (see below).
 */

const crypto = require('crypto');

const DEFAULT_JWKS_URI =
  'http://keycloak:8080/realms/space-fractions/protocol/openid-connect/certs';

/** OIDC authentication error (missing/invalid credentials -> HTTP 401). */
class AuthError extends Error {
  constructor(message) {
    super(message);
    this.name = 'AuthError';
    this.status = 401;
  }
}

/**
 * Extract the raw bearer token from an Authorization header.
 *   "Bearer <token>" -> "<token>"
 * Missing header or malformed scheme throws AuthError (401).
 *
 * @param {string|undefined} header
 * @returns {string}
 */
function bearerToken(header) {
  if (!header || typeof header !== 'string') {
    throw new AuthError('missing authorization header');
  }
  const match = /^Bearer\s+(\S+)$/i.exec(header.trim());
  if (!match) {
    throw new AuthError('malformed authorization header');
  }
  return match[1];
}

/**
 * Extract roles from a decoded JWT payload. Accepts the standard Keycloak
 * `realm_access.roles` claim plus an explicit `roles` array. Returns an array
 * (possibly empty).
 *
 * @param {object} payload
 * @returns {string[]}
 */
function extractRoles(payload) {
  if (payload && Array.isArray(payload.roles)) {
    return payload.roles.slice();
  }
  if (
    payload &&
    payload.realm_access &&
    Array.isArray(payload.realm_access.roles)
  ) {
    return payload.realm_access.roles.slice();
  }
  return [];
}

/** True when the payload carries the configured administrator role. */
function isAdmin(payload, adminRole) {
  const role = adminRole || process.env.OIDC_ADMIN_ROLE || 'admin';
  return extractRoles(payload).includes(role);
}

/** Base64url-decode a JWT segment. */
function b64urlDecode(segment) {
  const b64 = segment.replace(/-/g, '+').replace(/_/g, '/');
  const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
  return Buffer.from(padded, 'base64');
}

/** Decode a JWT into { header, payload, signature } without verifying. */
function decodeJwt(token) {
  const parts = String(token).split('.');
  if (parts.length !== 3) {
    throw new AuthError('malformed token');
  }
  let header;
  let payload;
  try {
    header = JSON.parse(b64urlDecode(parts[0]).toString('utf8'));
    payload = JSON.parse(b64urlDecode(parts[1]).toString('utf8'));
  } catch {
    throw new AuthError('malformed token');
  }
  return { header, payload, signature: parts[2] };
}

/**
 * Verify an RS/ES JWT signature against a JWK.
 *
 * Supports RS256/RS384/RS512 (RSA) and ES256 (EC P-256). Returns true when the
 * signature is valid. Throws AuthError on unsupported algorithms or bad JWK.
 */
function verifySignature(token, jwk) {
  const { header, signature } = decodeJwt(token);
  const alg = header.alg;
  const signingInput = token.split('.').slice(0, 2).join('.');

  const hashFor = (a) => {
    if (a === 'RS256' || a === 'ES256') return 'sha256';
    if (a === 'RS384' || a === 'ES384') return 'sha384';
    if (a === 'RS512' || a === 'ES512') return 'sha512';
    throw new AuthError(`unsupported algorithm: ${a}`);
  };

  const input = Buffer.from(signingInput, 'utf8');
  const sig = b64urlDecode(signature);

  if (alg.startsWith('RS')) {
    const key = crypto.createPublicKey({
      key: {
        kty: 'RSA',
        n: jwk.n,
        e: jwk.e,
      },
      format: 'jwk',
    });
    return crypto.verify(hashFor(alg), input, key, sig);
  }

  if (alg.startsWith('ES')) {
    const key = crypto.createPublicKey({
      key: {
        kty: 'EC',
        crv: jwk.crv || 'P-256',
        x: jwk.x,
        y: jwk.y,
      },
      format: 'jwk',
    });
    // ES signatures are raw r||s; Node expects DER. Convert.
    const r = sig.subarray(0, sig.length / 2);
    const s = sig.subarray(sig.length / 2);
    const der = derEncodeEcdsa(r, s);
    return crypto.verify(hashFor(alg), input, key, der);
  }

  throw new AuthError(`unsupported algorithm: ${alg}`);
}

/** Encode an ECDSA raw r||s signature into a minimal DER structure. */
function derEncodeEcdsa(r, s) {
  const toDerInt = (buf) => {
    let b = buf;
    while (b.length > 0 && b[0] === 0) b = b.subarray(1);
    if (b.length > 0 && b[0] & 0x80) b = Buffer.concat([Buffer.from([0]), b]);
    return Buffer.concat([Buffer.from([0x02, b.length]), b]);
  };
  const rInt = toDerInt(r);
  const sInt = toDerInt(s);
  const body = Buffer.concat([rInt, sInt]);
  return Buffer.concat([Buffer.from([0x30, body.length]), body]);
}

/**
 * Create a token verifier.
 *
 * @param {object} options
 * @param {string} [options.issuer]   expected issuer (env OIDC_ISSUER)
 * @param {string} [options.audience] expected audience (env OIDC_AUDIENCE, default "account")
 * @param {string} [options.jwksUri]  JWKS endpoint (env OIDC_JWKS_URI)
 * @param {object} [options.jwks]     preloaded JWKS JSON (injected for tests/no network)
 * @param {function} [options.fetch]  fetch implementation (default globalThis.fetch)
 * @param {number} [options.clockToleranceSeconds]
 * @returns {{ verify: (token: string) => Promise<object> }}
 */
function createTokenVerifier(options = {}) {
  const issuer = options.issuer || process.env.OIDC_ISSUER;
  const audience = options.audience || process.env.OIDC_AUDIENCE || 'account';
  const jwksUri = options.jwksUri || process.env.OIDC_JWKS_URI || DEFAULT_JWKS_URI;
  const fetchImpl = options.fetch || globalThis.fetch;
  const tolerance =
    (options.clockToleranceSeconds || 0) * 1000;
  const adminRole = process.env.OIDC_ADMIN_ROLE || 'admin';

  let cachedJwks = options.jwks || null;

  async function getJwks() {
    if (cachedJwks) return cachedJwks;
    if (typeof fetchImpl !== 'function') {
      throw new AuthError('no JWKS source configured');
    }
    const res = await fetchImpl(jwksUri, {
      headers: { accept: 'application/json' },
    });
    if (!res.ok) {
      throw new AuthError(`jwks fetch failed: ${res.status}`);
    }
    cachedJwks = await res.json();
    return cachedJwks;
  }

  async function verify(token) {
    const { header, payload } = decodeJwt(token);

    // 1. Signature against a matching JWK (kid preferred).
    const jwks = await getJwks();
    const keys = (jwks && jwks.keys) || [];
    const candidates = keys.filter(
      (k) => k.kty === 'RSA' || (k.kty === 'EC' && k.crv === 'P-256'),
    );
    const key =
      candidates.find((k) => k.kid && k.kid === header.kid) ||
      candidates[0];
    if (!key) {
      throw new AuthError('no matching key');
    }
    let valid = false;
    try {
      valid = verifySignature(token, key);
    } catch (err) {
      if (err instanceof AuthError) throw err;
      valid = false;
    }
    if (!valid) {
      throw new AuthError('invalid signature');
    }

    // 2. Issuer.
    if (issuer && payload.iss !== issuer) {
      throw new AuthError('invalid issuer');
    }

    // 3. Audience: accept string or array membership.
    const aud = payload.aud;
    const audOk = Array.isArray(aud)
      ? aud.includes(audience)
      : aud === audience;
    if (!audOk) {
      throw new AuthError('invalid audience');
    }

    // 4. Expiry with a small clock tolerance.
    const nowMs = Date.now();
    if (typeof payload.exp === 'number' && payload.exp * 1000 + tolerance < nowMs) {
      throw new AuthError('token expired');
    }
    if (typeof payload.nbf === 'number' && payload.nbf * 1000 - tolerance > nowMs) {
      throw new AuthError('token not yet valid');
    }

    return payload;
  }

  return { verify };
}

module.exports = {
  AuthError,
  bearerToken,
  decodeJwt,
  extractRoles,
  isAdmin,
  createTokenVerifier,
  verifySignature,
  derEncodeEcdsa,
  DEFAULT_JWKS_URI,
};

'use strict';

/**
 * Game repository — persistence layer for the game service.
 *
 * Provides two implementations behind a common interface:
 *   - PgGameRepository: PostgreSQL 16 source of truth. Score mutations are
 *     serialized per game and deduplicated in a single transaction; repeats
 *     rely on the UNIQUE (game_id, question_id) constraint in the `answers`
 *     table (sql/migrations/001_schema.sql) and are surfaced with a
 *     DUPLICATE_ANSWER code so the route layer can return 409.
 *   - InMemoryGameRepository: dependency-injection test adapter so the default
 *     `npm test` runs without live PostgreSQL while still exercising
 *     deduplication and owner checks.
 *
 * Repository interface consumed by packages/game-service/src/index.js:
 *   create(ownerId, questions)               -> {id,state,score}
 *   get(id)                                  -> game|null (contains questions
 *                                               WITH correctAnswer for scoring;
 *                                               the route layer strips it)
 *   setState(id, state)                      -> {id,state,score}
 *   scoreAnswer(id, questionId, answer, correct) -> Promise<{correct,score}>
 *        throws {code:'DUPLICATE_ANSWER'} on a repeated question
 *
 * Game shape (internal):
 *   { id, ownerId, state, score, questions: [{id,prompt,options,correctAnswer}] }
 */

const { Client } = require('pg');

/** Error thrown when a question has already been answered for a game (-> 409). */
class DuplicateAnswerError extends Error {
  constructor() {
    super('answer already recorded for this game');
    this.name = 'DuplicateAnswerError';
    this.code = 'DUPLICATE_ANSWER';
  }
}

/** snake_case game row -> internal game shape (questions filled separately). */
function rowToGame(row) {
  return {
    id: row.id,
    ownerId: row.owner_id,
    state: row.state,
    score: row.score,
    questions: [],
  };
}

/** snake_case question row -> internal question shape (correctAnswer kept). */
function rowToGameQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: Array.isArray(row.options) ? row.options.slice() : [],
    correctAnswer: row.correct_answer,
  };
}

/**
 * PostgreSQL-backed game repository.
 *
 * The pg Client opens its connection lazily (on first use) so the HTTP listener
 * can boot before Postgres is reachable; bounded downstream timeouts are layered
 * on by the service/gateway.
 *
 * Concurrency contract (space-fractions.md line 48): score updates serialize per
 * game via `SELECT ... FOR UPDATE` on the games row inside one owned
 * transaction. Both the answer INSERT and the score UPDATE happen in the same
 * transaction; the UNIQUE (game_id, question_id) constraint becomes the dedup
 * guard (no EXCLUDED in RETURNING — illegal on PG16). On any error the
 * transaction rolls back.
 */
class PgGameRepository {
  constructor(connectionString) {
    this.client = new Client({ connectionString });
  }

  async _ensureConnected() {
    if (!this._connected) {
      await this.client.connect();
      this._connected = true;
    }
  }

  async create(ownerId, questions) {
    await this._ensureConnected();
    await this.client.query('BEGIN');
    try {
      const gameRes = await this.client.query(
        `INSERT INTO games (owner_id, state, score)
         VALUES ($1, 'in_progress', 0)
         RETURNING id, owner_id, state, score`,
        [ownerId],
      );
      const game = rowToGame(gameRes.rows[0]);

      // Insert the ordered question set; position preserves stable order.
      for (let i = 0; i < questions.length; i += 1) {
        await this.client.query(
          `INSERT INTO game_questions (game_id, question_id, position)
           VALUES ($1, $2, $3)`,
          [game.id, questions[i].id, i],
        );
      }

      await this.client.query('COMMIT');

      // Attach the question records (including correctAnswer) for scoring and
      // the player-facing view (the route strips correctAnswer before sending).
      game.questions = questions.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: Array.isArray(q.options) ? q.options.slice() : [],
        correctAnswer: q.correctAnswer,
      }));
      return game;
    } catch (err) {
      await this.client.query('ROLLBACK');
      throw err;
    }
  }

  /** Load a game and its ordered questions, with correctAnswer for scoring. */
  async _loadGame(id) {
    const res = await this.client.query(
      `SELECT id, owner_id, state, score FROM games WHERE id = $1`,
      [id],
    );
    if (!res.rows.length) return null;
    const game = rowToGame(res.rows[0]);

    const qRes = await this.client.query(
      `SELECT q.id, q.prompt, q.options, q.correct_answer
         FROM game_questions gq
         JOIN questions q ON q.id = gq.question_id
        WHERE gq.game_id = $1
        ORDER BY gq.position ASC`,
      [id],
    );
    game.questions = qRes.rows.map(rowToGameQuestion);
    return game;
  }

  async get(id) {
    await this._ensureConnected();
    return this._loadGame(id);
  }

  async setState(id, state) {
    await this._ensureConnected();
    const res = await this.client.query(
      `UPDATE games SET state = $2, updated_at = now()
        WHERE id = $1
        RETURNING id, owner_id, state, score`,
      [id, state],
    );
    return res.rows.length ? rowToGame(res.rows[0]) : null;
  }

  /**
   * Record an answer and increment the score atomically.
   *
   * @param {number} id          game id
   * @param {number} questionId
   * @param {string} answer      submitted answer string (stored verbatim)
   * @param {boolean} correct    whether the answer is correct (pre-computed)
   * @returns {Promise<{correct:boolean, score:number}>}
   * @throws DuplicateAnswerError if this question was already answered
   */
  async scoreAnswer(id, questionId, answer, correct) {
    await this._ensureConnected();
    await this.client.query('BEGIN');
    try {
      // Serialize per game: lock the games row for the duration of the
      // transaction so concurrent answers to the same game cannot interleave.
      const lockRes = await this.client.query(
        `SELECT id, owner_id, state, score FROM games WHERE id = $1 FOR UPDATE`,
        [id],
      );
      if (!lockRes.rows.length) {
        await this.client.query('ROLLBACK');
        return null;
      }

      // Dedup guard: the UNIQUE constraint also protects this, but checking
      // first gives a deterministic 409 without relying on error-code parsing.
      const dup = await this.client.query(
        `SELECT 1 FROM answers WHERE game_id = $1 AND question_id = $2`,
        [id, questionId],
      );
      if (dup.rows.length) {
        await this.client.query('ROLLBACK');
        throw new DuplicateAnswerError();
      }

      await this.client.query(
        `INSERT INTO answers (game_id, question_id, answer, correct)
         VALUES ($1, $2, $3, $4)`,
        [id, questionId, answer, correct],
      );

      const updated = correct
        ? await this.client.query(
            `UPDATE games SET score = score + 1, updated_at = now()
              WHERE id = $1
              RETURNING id, owner_id, state, score`,
            [id],
          )
        : await this.client.query(
            `UPDATE games SET updated_at = now()
              WHERE id = $1
              RETURNING id, owner_id, state, score`,
            [id],
          );

      await this.client.query('COMMIT');
      const game = rowToGame(updated.rows[0]);
      return { correct, score: game.score };
    } catch (err) {
      // Only roll back if a transaction is still open (the duplicate path above
      // already rolled back before throwing).
      try {
        await this.client.query('ROLLBACK');
      } catch {
        /* already rolled back */
      }
      throw err;
    }
  }

  async close() {
    if (this._connected) {
      await this.client.end();
      this._connected = false;
    }
  }
}

/**
 * In-memory game repository for unit tests. Mirrors the PostgreSQL semantics
 * including deduplication (repeat answer does not increment score and throws
 * DuplicateAnswerError) so route tests exercise real behavior without a live
 * database.
 */
class InMemoryGameRepository {
  constructor() {
    this.rows = new Map();
    this.answers = new Map(); // `${gameId}:${questionId}` -> true
    this.nextId = 1;
  }

  async create(ownerId, questions) {
    const id = this.nextId++;
    const game = {
      id,
      ownerId,
      state: 'in_progress',
      score: 0,
      questions: questions.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: Array.isArray(q.options) ? q.options.slice() : [],
        correctAnswer: q.correctAnswer,
      })),
    };
    this.rows.set(id, game);
    return {
      id: game.id,
      ownerId: game.ownerId,
      state: game.state,
      score: game.score,
      questions: game.questions,
    };
  }

  async get(id) {
    const game = this.rows.get(id);
    if (!game) return null;
    return {
      id: game.id,
      ownerId: game.ownerId,
      state: game.state,
      score: game.score,
      questions: game.questions.map((q) => ({ ...q, options: q.options.slice() })),
    };
  }

  async setState(id, state) {
    const game = this.rows.get(id);
    if (!game) return null;
    game.state = state;
    return { id: game.id, ownerId: game.ownerId, state: game.state, score: game.score };
  }

  async scoreAnswer(id, questionId, answer, correct) {
    const game = this.rows.get(id);
    if (!game) return null;
    const key = `${id}:${questionId}`;
    if (this.answers.has(key)) {
      throw new DuplicateAnswerError();
    }
    this.answers.set(key, true);
    if (correct) game.score += 1;
    return { correct, score: game.score };
  }

  async close() {
    this.rows.clear();
    this.answers.clear();
  }
}

module.exports = {
  PgGameRepository,
  InMemoryGameRepository,
  DuplicateAnswerError,
  rowToGame,
  rowToGameQuestion,
};

'use strict';

/**
 * Game service — session lifecycle and scoring for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 17-24, 47-50; Architecture_View
 * Lines 79-145 ProcessView):
 *   - Create a game from the question pool (or an explicit questionIds list for
 *     reproducible practice). Never expose `correctAnswer` to players.
 *   - Fetch game state, pause/resume, submit answers, and read the score.
 *   - Owner authorization: a game may only be read/mutated by its owner
 *     (other users -> 403 or 404).
 *   - Per-game serialization of scoring and transactional deduplication: the
 *     UNIQUE (game_id, question_id) constraint prevents a repeat answer from
 *     incrementing the score.
 *   - Answering while paused -> 409. Answering a repeated question -> 409 (or
 *     idempotent 200; this implementation uses 409 for repeat).
 *
 * The service depends on three injectable collaborators so the default
 * `npm test` runs without PostgreSQL, Redis or an identity provider:
 *   - repository:       game persistence (see ./repository.js)
 *   - questionProvider: source of question records for new games
 *   - eventPublisher:   emits score events (see ./events.js, RabbitMQ)
 *   - verifier:         OIDC token verifier (shared src/shared/oidc.js)
 *   - userRepository:   sub -> numeric owner id mapping (user-service contract)
 *
 * All owner authorization is performed against the numeric internal user id
 * derived from the verified OIDC `sub`, matching the user-service's mapping
 * contract (space-fractions.md line 48).
 */

const express = require('express');
const { Client } = require('pg');

const oidc = require('../../shared/oidc');
const { validateAnswer } = require('../../shared/fraction');

const PORT = Number(process.env.GAME_SERVICE_PORT || process.env.PORT || 3001);

/** Ownership/authorization error (other user's game -> 403/404). */
class GameServiceError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'GameServiceError';
    this.status = status;
  }
}

/** Domain state names as stored in the `games.state` column. */
const GAME_STATE = {
  IN_PROGRESS: 'in_progress',
  PAUSED: 'paused',
  FINISHED: 'finished',
};

/**
 * Resolve the numeric owner id from an Authorization header, reusing the
 * user-service mapping contract (sub -> users.id) via an injected repository.
 *
 * @param {object} userRepository { findBySubject }
 * @param {object} verifier       { verify(token): Promise<payload> }
 * @param {string} [authorizationHeader]
 * @returns {Promise<number>} numeric internal user id
 * @throws {oidc.AuthError} missing/invalid credentials -> HTTP 401
 */
async function resolveOwner(userRepository, verifier, authorizationHeader, profile) {
  const token = oidc.bearerToken(authorizationHeader);
  const payload = await verifier.verify(token);
  const sub = payload.sub;
  const existing = await userRepository.findBySubject(sub);
  const user =
    existing ||
    (await userRepository.findOrCreateBySubject(
      sub,
      profile || payload.preferred_username || sub,
    ));
  return user.id;
}

/**
 * Strip `correctAnswer` from question records for player-facing responses.
 * The provider may return full records including correctAnswer (needed for
 * scoring); players must never receive it.
 */
function toPublicQuestion(q) {
  return { id: q.id, prompt: q.prompt, options: Array.isArray(q.options) ? q.options.slice() : [] };
}

/**
 * Build the game-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.repository]         game repository (pg or in-memory)
 * @param {object} [deps.questionProvider]   { list(), get(id) }
 * @param {object} [deps.eventPublisher]     { publishScore(gameId, score) }
 * @param {object} [deps.verifier]           OIDC verifier
 * @param {object} [deps.userRepository]     sub -> id mapping
 * @param {object} [deps.logger]             logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const repository = deps.repository;
  if (!repository) throw new Error('game-service requires a repository');
  const questionProvider = deps.questionProvider;
  if (!questionProvider) throw new Error('game-service requires a questionProvider');
  const eventPublisher = deps.eventPublisher || { publishScore: async () => {} };
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const userRepository = deps.userRepository;
  if (!userRepository) throw new Error('game-service requires a userRepository');
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'game-service' });
  });

  // Shared auth helper for route handlers.
  async function requireOwner(req, res) {
    try {
      return await resolveOwner(userRepository, verifier, req.headers.authorization);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        res.status(401).json({ error: 'unauthorized' });
        return null;
      }
      log.error('auth failed', err.message);
      res.status(500).json({ error: 'internal_error' });
      return null;
    }
  }

  /**
   * POST /api/games?questionIds=1,2,3
   *   body { questionIds?: number[] }   (reproducible practice)
   *   201 { id, questions:[{id,prompt,options}] }
   * The correctAnswer is never returned to the player.
   */
  app.post('/api/games', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    try {
      const requested = Array.isArray(req.body && req.body.questionIds)
        ? req.body.questionIds
        : null;

      let questions;
      if (requested && requested.length > 0) {
        questions = [];
        for (const qid of requested) {
          if (!Number.isInteger(qid) || qid <= 0) {
            return res.status(400).json({ error: 'invalid_question_id' });
          }
          const q = await questionProvider.get(qid);
          if (!q) return res.status(404).json({ error: 'question_not_found' });
          questions.push(q);
        }
      } else {
        questions = await questionProvider.list();
        // Stable order is guaranteed by the position column in the persistence
        // layer; the in-memory provider returns insertion order.
        if (!questions.length) {
          return res.status(404).json({ error: 'no_questions_available' });
        }
      }

      const game = await repository.create(ownerId, questions);
      await eventPublisher
        .publishScore(game.id, game.score)
        .catch((err) => log.warn('publishScore failed (non-fatal)', err.message));

      return res.status(201).json({
        id: game.id,
        state: GAME_STATE.IN_PROGRESS,
        questions: questions.map(toPublicQuestion),
      });
    } catch (err) {
      log.error('create game failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games/:id -> 200 game state (player view, never correctAnswer).
   * Other user's game -> 404 (do not leak existence).
   */
  app.get('/api/games/:id', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      return res.status(200).json({
        id: game.id,
        state: game.state,
        score: game.score,
        questions: (game.questions || []).map(toPublicQuestion),
      });
    } catch (err) {
      log.error('get game failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  // Shared pause/resume mutation helper.
  async function mutateState(req, res, nextState) {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      const updated = await repository.setState(id, nextState);
      return res.status(200).json({ id: updated.id, state: updated.state, score: updated.score });
    } catch (err) {
      log.error('set state failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  }

  app.post('/api/games/:id/pause', (req, res) => mutateState(req, res, GAME_STATE.PAUSED));
  app.post('/api/games/:id/resume', (req, res) => mutateState(req, res, GAME_STATE.IN_PROGRESS));

  /**
   * POST /api/games/:id/answers { questionId, answer }
   *   200 { correct:boolean, score:integer }
   *   400 malformed fraction / invalid payload
   *   409 paused game or repeated question
   * Scoring and dedup happen in one transaction in the repository.
   */
  app.post('/api/games/:id/answers', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    const body = req.body || {};
    const questionId = body.questionId;
    const answer = body.answer;
    if (!Number.isInteger(questionId) || questionId <= 0) {
      return res.status(400).json({ error: 'invalid_question_id' });
    }
    if (typeof answer !== 'string' || answer.trim() === '') {
      return res.status(400).json({ error: 'answer_must_be_string' });
    }

    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      if (game.state === GAME_STATE.PAUSED) {
        return res.status(409).json({ error: 'game_paused' });
      }
      // Validate the submitted answer is a well-formed fraction before scoring.
      const question = await questionProvider.get(questionId);
      if (!question) return res.status(404).json({ error: 'question_not_found' });
      const verdict = validateAnswer(question, answer);
      if (verdict.reason === 'answer_malformed') {
        return res.status(400).json({ error: 'malformed_fraction' });
      }

      // scoreAnswer deduplicates via UNIQUE(game_id, question_id); a repeat
      // throws a DuplicateAnswer error the repository surfaces as 409.
      const result = await repository.scoreAnswer(id, questionId, answer, verdict.correct);
      await eventPublisher
        .publishScore(id, result.score)
        .catch((err) => log.warn('publishScore failed (non-fatal)', err.message));

      return res.status(200).json({ correct: result.correct, score: result.score });
    } catch (err) {
      if (err && err.code === 'DUPLICATE_ANSWER') {
        return res.status(409).json({ error: 'answer_already_recorded' });
      }
      log.error('answer failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games/:id/score -> 200 { score:integer }. Other user -> 404.
   */
  app.get('/api/games/:id/score', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      return res.status(200).json({ score: game.score });
    } catch (err) {
      log.error('get score failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

/**
 * Build production dependencies (PostgreSQL repository, question pool provider
 * reading from the question-service's repository, RabbitMQ event publisher).
 * Kept lazy so the HTTP handler factory is importable in tests.
 */
function buildProductionDeps() {
  // Lazy requires keep the module importable without those files present until
  // a production runtime actually boots (test-time uses in-memory adapters).
  const { PgGameRepository } = require('./repository');
  const { RabbitMqEventPublisher } = require('./events');
  const { PgQuestionRepository } = require('../../question-service/src/repository');
  const { PgUserRepository } = require('../../user-service/src/index');

  const repository = new PgGameRepository(process.env.DATABASE_URL);
  const questionProvider = new PgQuestionRepository(process.env.DATABASE_URL);
  const userRepository = new PgUserRepository(process.env.DATABASE_URL);
  const eventPublisher = process.env.RABBITMQ_URL
    ? new RabbitMqEventPublisher(process.env.RABBITMQ_URL)
    : null;
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  return { repository, questionProvider, userRepository, eventPublisher, verifier };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const deps = buildProductionDeps();
  const app = buildApp(deps);
  const server = app.listen(PORT, () => {
    console.log(`game-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
  resolveOwner,
  toPublicQuestion,
  GAME_STATE,
  GameServiceError,
};

'use strict';

/**
 * User service — OIDC identity resolution and authorization for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 10-14, 37-44):
 *   - Validate a Bearer OIDC access token (issuer/audience/JWKS signature) via
 *     the shared `src/shared/oidc.js` helpers.
 *   - Map the verified `sub` claim to a numeric internal user id using the
 *     `users` table (UNIQUE subject) — creating the user lazily on first sight
 *     so authenticated players always have an owner id for game authorization.
 *   - Expose owner/admin authorization helpers consumed by the game-service and
 *     admin-service (the gateway fans out requests; this service is the single
 *     place that resolves JWT `sub` -> `users.id`).
 *
 * OIDC environment contract (space-fractions.md line 40):
 *   - OIDC_ISSUER  public issuer origin.
 *   - OIDC_JWKS_URI internal-certificates endpoint (default http://keycloak:8080/...).
 *   - OIDC_AUDIENCE expected audience (default "account").
 *   - OIDC_ADMIN_ROLE role name conferring administrator privileges (default "admin").
 *
 * The service boots its HTTP listener even when PostgreSQL is unreachable: the
 * pg `Client` connects lazily, and unit tests inject an in-memory repository.
 */

const express = require('express');
const { Client } = require('pg');

const oidc = require('../../shared/oidc');

const PORT = Number(process.env.USER_SERVICE_PORT || process.env.PORT || 3003);

/** Validation/authorization error helper (mirrors shared AuthError semantics). */
class UserServiceError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'UserServiceError';
    this.status = status;
  }
}

/**
 * Repository interface:
 *   findOrCreateBySubject(subject, profile) -> Promise<User>
 *   findBySubject(subject)                 -> Promise<User|null>
 *   findById(id)                           -> Promise<User|null>
 * where User = { id, subject, profile, roles }.
 */

/** PostgreSQL-backed user repository (source of truth: sql/migrations/001_schema.sql). */
class PgUserRepository {
  constructor(connectionString) {
    this.client = new Client({ connectionString });
  }

  async _ensureConnected() {
    if (!this._connected) {
      await this.client.connect();
      this._connected = true;
    }
  }

  async findOrCreateBySubject(subject, profile = '') {
    await this._ensureConnected();
    await this.client.query('BEGIN');
    try {
      // Lock-free upsert on the UNIQUE(subject) index; profile defaults applied
      // at creation but not overwritten on re-sight (name ownership preserved).
      const res = await this.client.query(
        `INSERT INTO users (subject, profile)
         VALUES ($1, $2)
         ON CONFLICT (subject) DO UPDATE SET updated_at = now()
         RETURNING id, subject, profile, roles`,
        [subject, profile],
      );
      await this.client.query('COMMIT');
      return rowToUser(res.rows[0]);
    } catch (err) {
      await this.client.query('ROLLBACK');
      throw err;
    }
  }

  async findBySubject(subject) {
    await this._ensureConnected();
    const res = await this.client.query(
      'SELECT id, subject, profile, roles FROM users WHERE subject = $1',
      [subject],
    );
    return res.rows.length ? rowToUser(res.rows[0]) : null;
  }

  async findById(id) {
    await this._ensureConnected();
    const res = await this.client.query(
      'SELECT id, subject, profile, roles FROM users WHERE id = $1',
      [id],
    );
    return res.rows.length ? rowToUser(res.rows[0]) : null;
  }

  async close() {
    if (this._connected) {
      await this.client.end();
      this._connected = false;
    }
  }
}

/** In-memory adapter for unit tests (no live PostgreSQL required). */
class InMemoryUserRepository {
  constructor() {
    this.rows = new Map(); // id -> User
    this.bySubject = new Map(); // subject -> id
    this.nextId = 1;
  }

  async findOrCreateBySubject(subject, profile = '') {
    const existing = await this.findBySubject(subject);
    if (existing) return existing;
    const id = this.nextId++;
    const user = { id, subject, profile, roles: [] };
    this.rows.set(id, user);
    this.bySubject.set(subject, id);
    return user;
  }

  async findBySubject(subject) {
    const id = this.bySubject.get(subject);
    return id ? this.rows.get(id) : null;
  }

  async findById(id) {
    return this.rows.get(id) || null;
  }

  async close() {
    this.rows.clear();
    this.bySubject.clear();
  }
}

function rowToUser(row) {
  return {
    id: row.id,
    subject: row.subject,
    profile: row.profile,
    roles: Array.isArray(row.roles) ? row.roles.slice() : [],
  };
}

/**
 * Resolve the authenticated identity from an Authorization header.
 *
 * Verifies the token, extracts `sub` and roles, and maps `sub` to the numeric
 * internal user id via the repository (lazily creating the user). Returns
 * { id, subject, profile, roles } on success.
 *
 * @param {object} repo       user repository
 * @param {object} verifier   OIDC token verifier ({ verify })
 * @param {string|undefined} authorizationHeader
 * @param {string} [profile]  profile name to persist on first sight
 * @returns {Promise<object>}
 */
async function authenticate(repo, verifier, authorizationHeader, profile) {
  const token = oidc.bearerToken(authorizationHeader);
  const payload = await verifier.verify(token);
  const sub = payload.sub;
  const roles = oidc.extractRoles(payload);
  const existing = await repo.findBySubject(sub);
  const principal = existing || (await repo.findOrCreateBySubject(sub, profile || payload.preferred_username || sub));
  return {
    id: principal.id,
    subject: sub,
    profile: principal.profile,
    roles,
  };
}

/**
 * Build the user-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.repository] user repository (pg or in-memory)
 * @param {object} [deps.verifier]   OIDC token verifier ({ verify })
 * @param {object} [deps.logger]     logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const repository = deps.repository || new InMemoryUserRepository();
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  // Health for orchestration/tests.
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'user-service' });
  });

  /**
   * Authenticate the bearer token and return the resolved principal. Used by
   * the gateway's downstream routing and by tests for owner/admin checks.
   *   200 {id, subject, profile, roles}
   *   401 missing/invalid credentials
   */
  app.post('/auth/verify', async (req, res) => {
    try {
      const principal = await authenticate(repository, verifier, req.headers.authorization);
      res.status(200).json(principal);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      log.error('auth verify failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Resolve a verified subject to its internal numeric id (no side effects when
   * the user already exists; lazily creates when absent). Mirrors /auth/verify
   * but makes the id-mapping contract explicit for the async service.
   *   200 {id, subject, profile}
   *   401 missing/invalid credentials
   */
  app.get('/users/me', async (req, res) => {
    try {
      const principal = await authenticate(repository, verifier, req.headers.authorization);
      res.status(200).json({
        id: principal.id,
        subject: principal.subject,
        profile: principal.profile,
        roles: principal.roles,
      });
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      log.error('users/me failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Fetch a user by numeric internal id (used by game/admin services to check
   * ownership without re-walking the token). No authorization requirement for a
   * read of profile metadata; secrets are never exposed.
   */
  app.get('/users/:id', async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'invalid_id' });
      }
      const user = await repository.findById(id);
      if (!user) return res.status(404).json({ error: 'not_found' });
      return res.status(200).json(user);
    } catch (err) {
      log.error('get user failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

function buildProductionDeps() {
  const repository = new PgUserRepository(process.env.DATABASE_URL);
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  return { repository, verifier };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const { repository, verifier } = buildProductionDeps();
  const app = buildApp({ repository, verifier });
  const server = app.listen(PORT, () => {
    console.log(`user-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
  authenticate,
  PgUserRepository,
  InMemoryUserRepository,
  UserServiceError,
};

'use strict';

/**
 * Score-event publisher — RabbitMQ integration for the game service.
 *
 * Emits a lightweight score event whenever a game is created or a correct
 * answer is recorded, so downstream consumers (metrics, leaderboards) can
 * react asynchronously without blocking the request path. This is a real
 * amqplib integration (space-fractions.md line 30): the channel is opened
 * lazily on the first publish, message publication is confirmed, and the
 * connection is bounded (open timeout) so a down broker fails fast instead of
 * hanging the HTTP handler. Publishing is always non-fatal to the route
 * (index.js catches publishScore failures and logs a warning).
 *
 * Event shape (JSON, a single UTF-8 Buffer):
 *   { gameId: number, score: number, at: ISO-8601 timestamp }
 *
 * Exchange/queue naming is fixed and documented against compose.yaml; the
 * durable queue is declared idempotently via assertQueue.
 */

const amqp = require('amqplib');

const EXCHANGE = 'space_fractions.scores';
const QUEUE = 'space_fractions.score_events';
const ROUTING_KEY = 'score.updated';

/** Milliseconds to wait for a broker connection before failing a publish. */
const CONNECT_TIMEOUT_MS = 2000;

/** Number of seconds to retain the declared queue after consumers disconnect. */
const QUEUE_MESSAGE_TTL_MS = 0; // unlimited; events are durable and small

/**
 * RabbitMQ-backed publisher.
 *
 * @param {string} url amqp:// connection string to the broker
 * @param {object} [options]
 * @param {number} [options.connectTimeoutMs]
 */
class RabbitMqEventPublisher {
  constructor(url, options = {}) {
    if (!url) throw new Error('RabbitMqEventPublisher requires a broker URL');
    this.url = url;
    this.connectTimeoutMs = options.connectTimeoutMs || CONNECT_TIMEOUT_MS;
    this.connection = null;
    this.channel = null;
  }

  async _ensureChannel() {
    if (this.channel) return this.channel;

    // Bound the connect so a down broker cannot hang the request path.
    const connection = await amqp.connect(this.url, { timeout: this.connectTimeoutMs });
    this.connection = connection;

    // Detach cleanly if the broker drops us mid-flight; the next publish will
    // reconnect lazily.
    connection.on('error', () => {
      this._reset();
    });
    connection.on('close', () => {
      this._reset();
    });

    const channel = await connection.createConfirmChannel();
    await channel.assertExchange(EXCHANGE, 'topic', { durable: true });
    // Declaring the queue keeps the topology explicit; durability ensures the
    // broker retains scored events across restarts.
    await channel.assertQueue(QUEUE, {
      durable: true,
      arguments: { 'x-message-ttl': QUEUE_MESSAGE_TTL_MS },
    });
    await channel.bindQueue(QUEUE, EXCHANGE, ROUTING_KEY);
    this.channel = channel;
    return channel;
  }

  _reset() {
    this.channel = null;
    this.connection = null;
  }

  /**
   * Publish a score event. Confirmation (publisher confirm) is awaited so the
   * caller knows the broker accepted the message; failures propagate to the
   * caller, which treats them as non-fatal to the HTTP response.
   *
   * @param {number} gameId
   * @param {number} score
   * @returns {Promise<boolean>} true once the broker confirms the publish
   */
  async publishScore(gameId, score) {
    const channel = await this._ensureChannel();
    const payload = Buffer.from(
      JSON.stringify({
        gameId,
        score,
        at: new Date().toISOString(),
      }),
    );
    return channel.publish(EXCHANGE, ROUTING_KEY, payload, {
      persistent: true,
      contentType: 'application/json',
    });
  }

  /** Close the channel/connection (idempotent). */
  async close() {
    try {
      if (this.channel) await this.channel.close();
    } catch {
      /* ignore */
    }
    try {
      if (this.connection) await this.connection.close();
    } catch {
      /* ignore */
    }
    this._reset();
  }
}

module.exports = {
  RabbitMqEventPublisher,
  EXCHANGE,
  QUEUE,
  ROUTING_KEY,
};

'use strict';

/**
 * QuestionSearch — Elasticsearch-backed question search adapter.
 *
 * Requirement (space-fractions.md line 9): "Search and metrics must have real
 * clients, not placeholder responses." This module wraps the official
 * @elastic/elasticsearch client and issues real index/search/delete requests
 * against a configured cluster. When constructed with a null client (unit tests
 * or environments without Elasticsearch), search degrades to a deterministic
 * local filtering adapter so `npm test` and service boot never require a live
 * cluster. The null path is an explicit DI fallback, not a placeholder that
 * masquerades as a real result.
 *
 * Index mapping (stable, single string fields only — questions carry a prompt
 * and string options; correct_answer is not analysed as a search field since
 * player-facing responses must never reveal it):
 *   questions:{id:long, prompt:text, options:keyword[]}
 *
 * Interface (consumed by packages/question-service/src/index.js):
 *   search(query) -> Promise<Array<{id,prompt,options,correctAnswer}>>
 *   index(question) -> Promise<void>
 *   remove(id) -> Promise<void>
 */

const QUESTION_INDEX = 'questions';

/** Canonical index mapping. Idempotent: ignored when the index already exists. */
const QUESTION_MAPPING = {
  properties: {
    id: { type: 'long' },
    prompt: { type: 'text' },
    options: { type: 'keyword' },
  },
};

/**
 * In-memory fallback used only when no Elasticsearch client is injected. Keeps
 * the search contract intact (same return shape) so route handlers and tests
 * exercise identical logic. Indexing/removal mirror the remote index so the
 * fallback remains a faithful stand-in rather than a no-op stub.
 */
class InMemoryQuestionIndex {
  constructor() {
    this.docs = new Map();
  }

  search(query) {
    const q = (query || '').trim().toLowerCase();
    const all = Array.from(this.docs.values());
    if (q === '') return all.slice();
    return all.filter((doc) => doc.prompt.toLowerCase().includes(q));
  }

  index(question) {
    this.docs.set(String(question.id), question);
  }

  remove(id) {
    this.docs.delete(String(id));
  }
}

class QuestionSearch {
  /**
   * @param {import('@elastic/elasticsearch').Client|null} client real ES client
   *   or null to use the deterministic in-memory fallback (DI/test path).
   * @param {object} [opts]
   * @param {function} [opts.logger] default console
   */
  constructor(client, opts = {}) {
    this.client = client;
    this.logger = opts.logger || console;
    if (!client) {
      this._fallback = new InMemoryQuestionIndex();
    }
  }

  /**
   * Ensure the questions index exists (idempotent). Only makes remote calls
   * when a real client is present.
   */
  async ensureIndex() {
    if (!this.client) return;
    const exists = await this.client.indices.exists({ index: QUESTION_INDEX });
    if (!exists.body) {
      await this.client.indices.create({
        index: QUESTION_INDEX,
        body: { mappings: QUESTION_MAPPING },
      });
    }
  }

  /** Full-text search over question prompts. */
  async search(query) {
    if (!this.client) {
      return this._fallback.search(query);
    }
    await this.ensureIndex();
    const q = (query || '').trim();
    const must = q === ''
      ? [{ match_all: {} }]
      : [{ match: { prompt: { query: q } } }];
    const res = await this.client.search({
      index: QUESTION_INDEX,
      body: { query: { bool: { must } } },
    });
    const hits = (res.body && res.body.hits && res.body.hits.hits) || [];
    return hits.map((h) => h._source);
  }

  /** Index a question document (best-effort from the caller's perspective). */
  async index(question) {
    if (!this.client) {
      this._fallback.index(question);
      return;
    }
    await this.ensureIndex();
    await this.client.index({
      index: QUESTION_INDEX,
      id: String(question.id),
      body: question,
      refresh: true,
    });
  }

  /** Remove a question document from the index. */
  async remove(id) {
    if (!this.client) {
      this._fallback.remove(id);
      return;
    }
    await this.client.delete({
      index: QUESTION_INDEX,
      id: String(id),
    });
  }
}

module.exports = { QuestionSearch, QUESTION_INDEX, QUESTION_MAPPING };

