 *
 * Responsibilities (space-fractions.md lines 15-24, 30-31):
 *   - GET /health -> 200 (orchestration/liveness probe).
 *   - Serve the plain browser UI (HTML/CSS/JS, no bundler) at "/".
 *   - Reverse-proxy authenticated API requests to the downstream services
 *     (game-service, question-service, user-service, admin-service), forwarding
 *     the Bearer OIDC access token verbatim so each service enforces its own
 *     authorization boundary.
 *   - Bounded downstream timeouts + error handling: a slow/unreachable service
 *     yields a 504/502, never an open socket.
 *   - Publish Prometheus metrics on GET /metrics.
 *   - Original GET /play backwards compatibility -> creates a practice game and
 *     returns { gameId } (Architecture_Documentation.md line 105).
 *
 * The gateway holds no domain state and performs no scoring/authorization of
 * its own. It computes the public browser origin from PUBLIC_ORIGIN (never a
 * hard-coded host:port) so Keycloak redirects work across remapped test ports.
 *
 * A reverse proxy with bounded timeouts is implemented on Node's built-in
 * `http` + global `fetch` (bounded via AbortController) rather than adding a
 * third-party proxy, keeping the runtime surface small and unit-testable —
 * injectable `routes`/`request` dependencies (see `buildApp`).
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = Number(process.env.PORT || 3000);

/** Per-downstream bounded timeout (ms) for API fan-out. */
const DOWNSTREAM_TIMEOUT_MS = Number(process.env.GATEWAY_TIMEOUT_MS || 10000);

/** Maximum forwarded request body (aligns with each service's `1mb` JSON limit). */
const MAX_BODY_BYTES = 1024 * 1024;

/** Default public-facing origin used for browser redirects/links. */
function publicOrigin() {
  return process.env.PUBLIC_ORIGIN || `http://localhost:${PORT}`;
}

/**
 * Read the static UI directory once (memoized). Returns a map of
 * relative-path -> { contentType, body } for every file under `public/`.
 */
function loadStaticAssets(staticDir) {
  const dir = staticDir || path.join(__dirname, '..', 'public');
  const assets = new Map();
  const walkAndRead = (base, relative) => {
    const entries = fs.readdirSync(base, { withFileTypes: true });
    for (const entry of entries) {
      const abs = path.join(base, entry.name);
      const rel = relative ? `${relative}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        walkAndRead(abs, rel);
      } else {
        assets.set(`/${rel}`, {
          contentType: contentTypeFor(rel),
          body: fs.readFileSync(abs),
        });
      }
    }
  };
  walkAndRead(dir, '');
  return assets;
}

function contentTypeFor(file) {
  if (file.endsWith('.html')) return 'text/html; charset=utf-8';
  if (file.endsWith('.css')) return 'text/css; charset=utf-8';
  if (file.endsWith('.js')) return 'application/javascript; charset=utf-8';
  if (file.endsWith('.json')) return 'application/json; charset=utf-8';
  if (file.endsWith('.svg')) return 'image/svg+xml';
  return 'application/octet-stream';
}

/**
 * Lightweight metrics registry (no external client required for the core
 * counters). Exposed as the standard Prometheus text format. Counters:
 *   http_requests_total{method,path,status}
 *   downstream_requests_total{service,status}
 *   downstream_timeouts_total{service}
 */
function createMetrics() {
  const counters = new Map();
  const inc = (name, labels) => {
    const key = `${name}{${Object.entries(labels).map(([k, v]) => `${k}="${v}"`).join(',')}}`;
    counters.set(key, (counters.get(key) || 0) + 1);
  };
  return {
    inc,
    render() {
      const lines = [];
      for (const [key, value] of counters.entries()) {
        lines.push(`${key} ${value}`);
      }
      return `${lines.join('\n')}\n`;
    },
  };
}

/**
 * Message shape expected from a downstream service URL: either a base URL
 * string, or an object { base, service } where `service` is the metrics label.
 */
function resolveTarget(entry) {
  if (typeof entry === 'string') return { base: entry, service: entry };
  return { base: entry.base, service: entry.service };
}

/**
 * Build the gateway HTTP request handler.
 *
 * @param {object} [deps]
 * @param {Map<string,object>} [deps.assets]  static asset map (loadStaticAssets)
 * @param {object}            [deps.routes]  { prefix: string|{base,service} }
 *   mapping URL prefixes to downstream base URLs (e.g. { '/api/games': 'http://game-service:3001' }).
 * @param {function}          [deps.fetch]   fetch implementation (default global fetch)
 * @param {object}            [deps.metrics] metrics registry (default createMetrics())
 * @param {object}            [deps.logger]  logger (default console)
 * @returns {http.RequestListener}
 */
function buildApp(deps = {}) {
  const assets = deps.assets || loadStaticAssets();
  const routes = deps.routes || defaultRoutes();
  const fetchImpl = deps.fetch || globalThis.fetch;
  const metrics = deps.metrics || createMetrics();
  const log = deps.logger || console;
  const origin = deps.publicOrigin || publicOrigin();

  async function readBody(req) {
    const chunks = [];
    let size = 0;
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        const err = new Error('request body too large');
        err.status = 413;
        throw err;
      }
      chunks.push(chunk);
    }
    return Buffer.concat(chunks);
  }

  function respond(res, status, headers, body) {
    res.writeHead(status, headers);
    res.end(body);
  }

  function json(res, status, obj) {
    respond(
      res,
      status,
      { 'content-type': 'application/json; charset=utf-8' },
      JSON.stringify(obj),
    );
  }

  /**
   * Forward an incoming request to the selected downstream target with a
   * bounded timeout. Returns { status, headers, body } on success; throws on
   * timeout (504) or refusal (502).
   */
  async function forward(req, target, body) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), DOWNSTREAM_TIMEOUT_MS);
    const url = new URL(req.url, target.base);
    try {
      const upstream = await fetchImpl(url.toString(), {
        method: req.method,
        headers: {
          'content-type': req.headers['content-type'] || 'application/json',
          // Forward the Bearer token verbatim so downstream services authorize.
          ...(req.headers.authorization
            ? { authorization: req.headers.authorization }
            : {}),
          accept: 'application/json',
        },
        body: req.method === 'GET' || req.method === 'HEAD' ? undefined : body,
        signal: controller.signal,
      });
      const resBody = await upstream.arrayBuffer();
      return {
        status: upstream.status,
        headers: upstream.headers,
        body: Buffer.from(resBody),
      };
    } catch (err) {
      if (err && err.name === 'AbortError') {
        const e = new Error(`downstream timeout: ${target.service}`);
        e.status = 504;
        throw e;
      }
      const e = new Error(`downstream unavailable: ${target.service}`);
      e.status = 502;
      throw e;
    } finally {
      clearTimeout(timer);
    }
  }

  function forwardableHeaders(headers) {
    const out = { 'content-type': 'application/json; charset=utf-8' };
    for (const key of ['content-type', 'cache-control', 'etag']) {
      if (headers && headers.get && headers.get(key)) out[key] = headers.get(key);
    }
    return out;
  }

  async function handle(req, res) {
    const parsed = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const pathname = parsed.pathname;
    const start = Date.now();

    try {
      // Liveness/readiness.
      if (pathname === '/health') {
        metrics.inc('http_requests_total', { method: 'GET', path: '/health', status: 200 });
        return json(res, 200, { status: 'ok', service: 'gateway' });
      }

      // Prometheus scrape endpoint.
      if (pathname === '/metrics') {
        metrics.inc('http_requests_total', { method: 'GET', path: '/metrics', status: 200 });
        return respond(res, 200, { 'content-type': 'text/plain; version=0.0.4; charset=utf-8' }, metrics.render());
      }

      // Original GET /play compatibility -> create a practice game, return gameId.
      if (pathname === '/play' && req.method === 'GET') {
        const gameTarget = resolveTarget(routes['/api/games']);
        const body = Buffer.from('{}');
        const { status, headers, body: resBody } = await forward(
          { ...req, url: '/api/games', method: 'POST' },
          gameTarget,
          body,
        );
        let gameId = null;
        try {
          const created = JSON.parse(resBody.toString('utf8'));
          gameId = created.id;
        } catch {
          /* downstream already errored */
        }
        const finalStatus = status < 400 && gameId ? 200 : status;
        metrics.inc('downstream_requests_total', { service: gameTarget.service, status });
        metrics.inc('http_requests_total', { method: 'GET', path: '/play', status: finalStatus });
        if (gameId) return json(res, finalStatus, { gameId });
        return respond(res, status, forwardableHeaders(headers), resBody);
      }

      // Static UI (served at "/", plus assets referenced by index.html).
      if (req.method === 'GET' || req.method === 'HEAD') {
        const assetPath = pathname === '/' ? '/index.html' : pathname;
        const asset = assets.get(assetPath);
        if (asset) {
          metrics.inc('http_requests_total', { method: req.method, path: pathname, status: 200 });
          const headers = { 'content-type': asset.contentType, 'cache-control': 'no-cache' };
          return respond(res, 200, headers, req.method === 'HEAD' ? undefined : asset.body);
        }
      }

      // API fan-out: longest matching prefix.
      const matching = Object.keys(routes)
        .filter((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`))
        .sort((a, b) => b.length - a.length)[0];
      if (matching) {
        const target = resolveTarget(routes[matching]);
        const body = req.method === 'GET' || req.method === 'HEAD' ? undefined : await readBody(req);
        const { status, headers, body: resBody } = await forward(req, target, body);
        metrics.inc('downstream_requests_total', { service: target.service, status });
        metrics.inc('http_requests_total', { method: req.method, path: pathname, status });
        return respond(res, status, forwardableHeaders(headers), resBody);
      }

      metrics.inc('http_requests_total', { method: req.method, path: pathname, status: 404 });
      return json(res, 404, { error: 'not_found' });
    } catch (err) {
      const status = err && err.status ? err.status : 500;
      log.error(`gateway error on ${req.method} ${pathname}`, err.message);
      metrics.inc('http_requests_total', { method: req.method, path: pathname, status });
      if (status === 504) {
        const serviceLabel = (err.service || 'unknown');
        metrics.inc('downstream_timeouts_total', { service: serviceLabel });
      }
      return json(res, status, { error: status === 504 ? 'gateway_timeout' : status === 502 ? 'bad_gateway' : 'internal_error' });
    }
  }

  return handle;
}

/** Default downstream routes resolved from env with container defaults. */
function defaultRoutes() {
  return {
    '/api/games': process.env.GAME_SERVICE_URL || 'http://game-service:3001',
    '/api/questions': process.env.QUESTION_SERVICE_URL || 'http://question-service:3002',
    '/api/users': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/users': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/auth': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/api/admin': process.env.ADMIN_SERVICE_URL || 'http://admin-service:3004',
  };
}

/**
 * Start the gateway HTTP listener (kept alive until SIGTERM/SIGINT).
 * The listener stays alive independently of downstream availability, so the
 * startup probe passes even before backing services are ready.
 */
function startServer(app, port) {
  const server = http.createServer(app);
  server.listen(port, () => {
    console.log(`gateway listening on :${port}`);
  });
  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
  return server;
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  startServer(buildApp(process.env.GATEWAY_STATIC_DIR ? {
    assets: loadStaticAssets(process.env.GATEWAY_STATIC_DIR),
  } : {}), PORT);
}

module.exports = {
  buildApp,
  loadStaticAssets,
  createMetrics,
  defaultRoutes,
  startServer,
  publicOrigin,
  contentTypeFor,
};

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');

const {
  gcd,
  normalize,
  parseFraction,
  formatFraction,
  toFraction,
  equals,
  compare,
  add,
  subtract,
  multiply,
  divide,
  validateAnswer,
} = require('../src/shared/fraction');

test('parseFraction accepts an integer', () => {
  assert.deepEqual(parseFraction('3'), { numerator: 3, denominator: 1 });
  assert.deepEqual(parseFraction('-7'), { numerator: -7, denominator: 1 });
});

test('parseFraction normalizes simple fractions', () => {
  assert.deepEqual(parseFraction('2/4'), { numerator: 1, denominator: 2 });
  assert.deepEqual(parseFraction('-3/4'), { numerator: -3, denominator: 4 });
  // sign on the denominator is carried to the numerator
  assert.deepEqual(parseFraction('5/-6'), { numerator: -5, denominator: 6 });
});

test('parseFraction accepts mixed numbers', () => {
  assert.deepEqual(parseFraction('1 1/2'), { numerator: 3, denominator: 2 });
  assert.deepEqual(parseFraction('-2 3/4'), { numerator: -11, denominator: 4 });
});

test('parseFraction rejects malformed and invalid input', () => {
  assert.equal(parseFraction('1/0'), null);
  assert.equal(parseFraction('abc'), null);
  assert.equal(parseFraction(''), null);
  assert.equal(parseFraction('   '), null);
  assert.equal(parseFraction('1/2/3'), null);
  assert.equal(parseFraction(null), null);
  assert.equal(parseFraction(5), null);
  assert.equal(parseFraction('1 /'), null);
});

test('formatFraction produces canonical strings', () => {
  assert.equal(formatFraction({ numerator: 1, denominator: 2 }), '1/2');
  assert.equal(formatFraction({ numerator: 2, denominator: 4 }), '1/2');
  assert.equal(formatFraction({ numerator: 4, denominator: 1 }), '4');
  assert.equal(formatFraction({ numerator: 0, denominator: 7 }), '0');
  assert.equal(formatFraction({ numerator: 1, denominator: 0 }), null);
  assert.equal(formatFraction(null), null);
});

test('equals compares equivalent fraction representations exactly', () => {
  assert.equal(equals('1/2', '2/4'), true);
  assert.equal(equals({ numerator: 1, denominator: 2 }, '3/6'), true);
  assert.equal(equals('1/2', '3/4'), false);
  assert.equal(equals('1/2', 'not-a-fraction'), false);
});

test('compare orders fractions exactly', () => {
  assert.equal(compare('1/2', '2/4'), 0);
  assert.equal(compare('1/3', '1/2'), -1);
  assert.equal(compare('3/4', '1/2'), 1);
  assert.ok(Number.isNaN(compare('x', '1/2')));
});

test('arithmetic operations are exact and normalized', () => {
  assert.deepEqual(add('1/4', '1/4'), { numerator: 1, denominator: 2 });
  assert.deepEqual(subtract('3/4', '1/4'), { numerator: 1, denominator: 2 });
  assert.deepEqual(multiply('2/3', '3/4'), { numerator: 1, denominator: 2 });
  assert.deepEqual(divide('1/2', '1/4'), { numerator: 2, denominator: 1 });
  assert.equal(divide('1/2', '0'), null);
});

test('gcd returns a positive divisor and handles zero', () => {
  assert.equal(gcd(12, 8), 4);
  assert.equal(gcd(-12, 8), 4);
  assert.equal(gcd(0, 5), 5);
  assert.equal(gcd(0, 0), 1);
});

test('normalize returns null for a zero denominator', () => {
  assert.equal(normalize(1, 0), null);
  assert.deepEqual(normalize(-4, -8), { numerator: 1, denominator: 2 });
});

test('toFraction coerces strings and objects and rejects bad values', () => {
  assert.deepEqual(toFraction('2/4'), { numerator: 1, denominator: 2 });
  assert.deepEqual(toFraction({ numerator: 2, denominator: 4 }), { numerator: 1, denominator: 2 });
  assert.equal(toFraction({ numerator: 1.5, denominator: 2 }), null);
  assert.equal(toFraction(null), null);
  assert.equal(toFraction(42), null);
});

test('validateAnswer scores exact rational equivalence', () => {
  const question = { correctAnswer: '1/2' };
  assert.deepEqual(validateAnswer(question, '2/4'), { correct: true });
  assert.deepEqual(validateAnswer(question, '1/2'), { correct: true });
  assert.deepEqual(validateAnswer(question, '3/4'), { correct: false });
});

test('validateAnswer handles malformed answers and missing correct answers', () => {
  assert.deepEqual(validateAnswer({ correctAnswer: '1/2' }, 'not-a-fraction'), {
    correct: false,
    reason: 'answer_malformed',
  });
  assert.deepEqual(validateAnswer({ correctAnswer: 'bad' }, '1/2'), {
    correct: false,
    reason: 'question_correct_answer_invalid',
  });
  assert.deepEqual(validateAnswer({}, '1/2'), {
    correct: false,
    reason: 'question_correct_answer_missing',
  });
  assert.deepEqual(validateAnswer({ correctAnswer: '1/2' }, 5), {
    correct: false,
    reason: 'answer_not_string',
  });
});

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');

const { buildApp, GAME_STATE } = require('../packages/game-service/src/index');
const {
  InMemoryGameRepository,
  DuplicateAnswerError,
} = require('../packages/game-service/src/repository');
const { validateAnswer } = require('../src/shared/fraction');

/**
 * Scoring and pause/resume behavior tests for the game service.
 *
 * These use the in-memory repository plus fake collaborators so the default
 * `npm test` runs without PostgreSQL, Redis, RabbitMQ or an identity provider,
 * while still exercising the real route handlers, transactional deduplication
 * semantics and owner authorization (space-fractions.md lines 20-24, 32-34).
 */

/** A fake OIDC verifier that claims any presented Bearer token as `sub`. */
function makeVerifier(sub = 'student-sub') {
  return {
    async verify() {
      return { sub, preferred_username: 'student' };
    },
  };
}

/** A fake user repository mapping a subject to a numeric internal user id. */
function makeUserRepository(idMap = {}) {
  const values = Object.assign({ 'student-sub': 1, 'other-sub': 2 }, idMap);
  return {
    async findBySubject(sub) {
      const id = values[sub];
      return id === undefined ? null : { id, subject: sub };
    },
    async findOrCreateBySubject(sub) {
      if (values[sub] === undefined) values[sub] = Math.max(...Object.values(values), 0) + 1;
      return { id: values[sub], subject: sub };
    },
  };
}

const QUESTIONS = [
  { id: 1, prompt: 'What is 1/2 + 1/4?', options: ['3/4', '2/6', '1/4'], correctAnswer: '3/4' },
  { id: 2, prompt: 'What is 1/2 of 2/3?', options: ['1/3', '2/6', '1/6'], correctAnswer: '1/3' },
  { id: 3, prompt: 'What is 3/4 - 1/2?', options: ['1/2', '1/4', '5/4'], correctAnswer: '1/4' },
];

/** A fake question provider exposing the fixed pool. */
function makeQuestionProvider(questions = QUESTIONS) {
  return {
    async list() {
      return questions.map((q) => ({ ...q, options: q.options.slice() }));
    },
    async get(id) {
      const q = questions.find((x) => x.id === id);
      return q ? { ...q, options: q.options.slice() } : null;
    },
  };
}

/** Create a game and return its id plus request/answer helpers. */
async function makeGame(jwtSub = 'student-sub', app = null) {
  const a = app || makeApp();
  const createRes = await request(app, a.app).post('/api/games', {}, auth(jwtSub));
  assert.equal(createRes.status, 201, 'game creation should succeed');
  return { id: createRes.body.id, app: a };
}

function auth(sub = 'student-sub') {
  return { authorization: `Bearer token-for-${sub}` };
}

function makeApp() {
  const repository = new InMemoryGameRepository();
  const app = buildApp({
    repository,
    questionProvider: makeQuestionProvider(),
    verifier: makeVerifier(),
    userRepository: makeUserRepository(),
    eventPublisher: { publishScore: async () => {} },
  });
  return { app, repository };
}

/** Minimal in-process HTTP helper around the Express app (no live listener). */
function httpInvoke(app) {
  return {
    post(path, body, headers = {}) {
      return invoke(app, 'POST', path, body, headers);
    },
    get(path, headers = {}) {
      return invoke(app, 'GET', path, null, headers);
    },
  };
}

function invoke(app, method, path, body, headers) {
  return new Promise((resolve, reject) => {
    const req = {
      method,
      url: path,
      headers: Object.assign({ 'content-type': 'application/json' }, headers),
      body: body === null ? undefined : body,
    };
    const res = {
      statusCode: 200,
      body: undefined,
      _headers: {},
      status(code) {
        this.statusCode = code;
        return this;
      },
      set() {
        return this;
      },
      json(obj) {
        this.body = obj;
        return this;
      },
      end() {},
    };
    res.on = () => {};
    // Capture when the handler finishes synchronously or errors.
    try {
      app.handle(req, res, (err) => {
        if (err) return reject(err);
        resolve({ status: res.statusCode, body: res.body });
      });
    } catch (err) {
      reject(err);
    }
  });
}

// Bind app.handle for readability.
const request = app => httpInvoke(app instanceof Function ? app : app.app);

test('each correct answer counts one point and exposes no correctAnswer', async () => {
  const a = makeApp();
  const created = await request(a.app).post('/api/games', {}, auth());
  assert.equal(created.status, 201);
  for (const q of created.body.questions) {
    assert.equal('correctAnswer' in q, false, 'players must never receive correctAnswer');
  }
  const id = created.body.id;
  assert.equal(id, 1);

  const r1 = await request(a.app).post(`/api/games/${id}/answers`, { questionId: 1, answer: '3/4' }, auth());
  assert.equal(r1.status, 200);
  assert.deepEqual(r1.body, { correct: true, score: 1 });

  const r2 = await request(a.app).post(`/api/games/${id}/answers`, { questionId: 2, answer: '1/3' }, auth());
  assert.equal(r2.status, 200);
  assert.deepEqual(r2.body, { correct: true, score: 2 });

  const r3 = await request(a.app).post(`/api/games/${id}/answers`, { questionId: 3, answer: '2/4' }, auth());
  assert.equal(r3.status, 200);

  const score = await request(a.app).get(`/api/games/${id}/score`, auth());
  assert.equal(score.status, 200);
  assert.deepEqual(score.body, { score: 3 });
});

test('an incorrect answer does not increment the score', async () => {
  const a = makeApp();
  const created = await request(a.app).post('/api/games', {}, auth());
  const id = created.body.id;

  const r = await request(a.app).post(`/api/games/${id}/answers`, { questionId: 1, answer: '1/2' }, auth());
  assert.equal(r.status, 200);
  assert.deepEqual(r.body, { correct: false, score: 0 });

  const score = await request(a.app).get(`/api/games/${id}/score`, auth());
  assert.deepEqual(score.body, { score: 0 });
});

test('repeating a question answer returns 409 and does not double-count', async () => {
  const a = makeApp();
  const created = await request(a.app).post('/api/games', { questionIds: [1] }, auth());
  const id = created.body.id;

  const first = await request(a.app).post(`/api/games/${id}/answers`, { questionId: 1, answer: '3/4' }, auth());
  assert.equal(first.status, 200);
  assert.equal(first.body.score, 1);

  const repeat = await request(a.app).post(`/api/games/${id}/answers`, { questionId: 1, answer: '3/4' }, auth());
  assert.equal(repeat.status, 409);

  const score = await request(a.app).get(`/api/games/${id}/score`, auth());
  assert.deepEqual(score.body, { score: 1 });
});

test('the in-memory repository deduplicates directly (transactional contract)', async () => {
  const repo = new InMemoryGameRepository();
  const game = await repo.create(1, QUESTIONS);
  const r1 = await repo.scoreAnswer(game.id, 1, '3/4', true);
  assert.deepEqual(r1, { correct: true, score: 1 });

  await assert.rejects(() => repo.scoreAnswer(game.id, 1, '3/4', true), DuplicateAnswerError);
  const g = await repo.get(game.id);
  assert.equal(g.score, 1, 'repeat answer must not increment score');
});

