'use strict';

/**
 * Shared in-process HTTP helper for Express-route tests.
 *
 * Express 4 middleware (expressInit), res.json() and res.send() all require a
 * real Node http.ServerResponse (setHeader/getHeader/end/...). Hand-rolled
 * mock response objects are brittle, so this module instead binds the Express
 * app to a real ephemeral HTTP server (port 0) and performs an actual in-process
 * request/response round trip via node:http. No external services are required,
 * so the default `npm test` runs without PostgreSQL, Redis, RabbitMQ,
 * Elasticsearch or a live identity provider.
 */

const http = require('node:http');

/**
 * Build a request helper bound to an Express app via a real ephemeral server.
 *
 * @param {import('express').Express} app
 * @returns {{ post(url, body, headers), get(url, headers), delete(url, headers), close() }}
 */
function createInvoker(app) {
  const server = http.createServer(app);

  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const address = server.address();
      const base = `http://127.0.0.1:${address.port}`;

      function request(method, path, body, headers = {}) {
        return new Promise((res, rej) => {
          const payload = body === undefined || body === null ? null : JSON.stringify(body);
          const req = http.request(
            {
              host: '127.0.0.1',
              port: address.port,
              method,
              path,
              headers: Object.assign(
                payload === null
                  ? {}
                  : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) },
                headers,
              ),
            },
            (response) => {
              const chunks = [];
              response.on('data', (c) => chunks.push(c));
              response.on('end', () => {
                const text = Buffer.concat(chunks).toString('utf8');
                let body = undefined;
                if (text) {
                  try {
                    body = JSON.parse(text);
                  } catch {
                    body = text;
                  }
                }
                res({ status: response.statusCode, body });
              });
            },
          );
          req.on('error', rej);
          if (payload !== null) req.write(payload);
          req.end();
        });
      }

      const invoker = {
        post: (path, body, headers) => request('POST', path, body, headers),
        get: (path, headers) => request('GET', path, undefined, headers),
        delete: (path, headers) => request('DELETE', path, undefined, headers),
        close: () =>
          new Promise((res) => {
            server.close(() => res());
          }),
      };

      // Keep the base around for optional debugging.
      invoker.base = base;
      resolve(invoker);
    });
  });
}

module.exports = { createInvoker };

// Build/verification script: performs real source checks rather than a no-op.
// Validates the syntax of every JavaScript source file (src/, packages/*/src,
// packages/gateway/public) using `node --check`, and confirms that the root
// contract artifacts (openapi.yaml, internal.proto) exist and are non-empty.
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, extname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const failures = [];

function collectJsFiles(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    if (entry === 'node_modules') continue;
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) collectJsFiles(full, out);
    else if (extname(entry) === '.js' || extname(entry) === '.mjs') out.push(full);
  }
  return out;
}

const jsFiles = collectJsFiles(root);
for (const file of jsFiles) {
  const res = spawnSync(process.execPath, ['--check', file], { encoding: 'utf8' });
  if (res.status !== 0) {
    failures.push(`${relative(root, file)}: ${(res.stderr || res.stdout || 'syntax error').trim()}`);
  }
}

const contractFiles = ['openapi.yaml', 'internal.proto', 'compose.yaml'];
for (const file of contractFiles) {
  let content = '';
  try {
    content = readFileSync(join(root, file), 'utf8');
  } catch {
    failures.push(`${file}: missing required contract artifact`);
    continue;
  }
  if (content.trim().length === 0) failures.push(`${file}: empty contract artifact`);
}

if (failures.length > 0) {
  console.error('Build checks failed:');
  for (const f of failures) console.error(`  - ${f}`);
  process.exit(1);
}

console.log(`Build checks passed: ${jsFiles.length} JS files valid, contract artifacts present.`);

