}

/** A fake user repository mapping a subject to a numeric internal user id. */
function makeUserRepository(idMap = {}) {
  const values = Object.assign({ 'student-sub': 1, 'other-sub': 2 }, idMap);
  return {
    async findBySubject(sub) {
